def calcCntAtPrefix(a):
    cntAtPrefix = [[0] * (len(a) + 1)]
    for i, x in enumerate(a):
        cntAtPrefix.append(cntAtPrefix[-1][:])
        cntAtPrefix[-1][x] += 1
    return cntAtPrefix

