    def inc():
        for i in range(n - 1):
            if a[i] > a[i + 1]:
                return False
        return True
    def calc():
        for i in range(n + 1):
            c[i] = 0
        for i in a:
            c[i] += 1
        for i in range(n + 1):
            if not c[i]:
                return i
        return n + 1
    ans = []
    while not inc():
        x = calc()
