def get_num (a, b):
    nonlocal dp
    if ((a,b) in dp):
        return dp[(a,b)]
    if (a < 0 or b < 0):
        return 0 
    if (a == 0 and b == 0):
        return 1

    a_bin = get_bin(a)
    b_bin = get_bin(b)

    if(b>a):
        a_bin,b_bin=b_bin,a_bin
        a,b=b,a

    if (len(a_bin)>len(b_bin)):
        big_bit = 1 << (len(a_bin) - 1)
        to_ret=((get_num(big_bit-1,b) + get_num(a-big_bit, b)))
