                right[i] = right[i+1] + cardPoints[i]

        for i in range(k+1) :
            if i == 0 : Sum = right[-k]
            elif i == k : Sum = left[k-1]
            else : 
                Sum = left[k-i-1] + right[-i]
            answer = max(answer,Sum)
        return answer

