class Solution:
    def totalFruit(self, tree: List[int]) -> int:
        prior_fruit = tree[0]
        prior_fruit_counter = 0
        fruits_in_basket = [tree[0]]
        fruits_in_basket_counter = 0
        max_fib = -1
        for fruit in tree: 
            if prior_fruit == fruit:
                prior_fruit_counter += 1
                fruits_in_basket_counter += 1
            elif prior_fruit != fruit:
                if fruit in fruits_in_basket:
                    fruits_in_basket_counter += 1
                else:
                    fruits_in_basket, fruits_in_basket_counter = [prior_fruit, fruit], prior_fruit_counter + 1
                prior_fruit, prior_fruit_counter = fruit, 1
            if fruits_in_basket_counter > max_fib:
                max_fib = fruits_in_basket_counter
        return max_fib

class Solution:
    def totalFruit(self, tree: List[int]) -> int:
        best_so_far = start = 0
        fruit_1 = fruit_2 = fruit_1_last_index = fruit_2_last_index = None

        for end in range(len(tree)):
            if fruit_1 is None:
                fruit_1 = tree[end]
                fruit_1_last_index = end

            elif fruit_2 is None and tree[end] != fruit_1:
                fruit_2 = tree[end]
                fruit_2_last_index = end

            else:
                if tree[end] == fruit_1:
                    fruit_1_last_index = end
                elif tree[end] == fruit_2:
                    fruit_2_last_index = end
                else:
                    best_so_far = max(best_so_far, end - start)

                    if fruit_1_last_index < fruit_2_last_index:
                        start = fruit_1_last_index + 1
                        fruit_1 = tree[end]
                        fruit_1_last_index = end
                    else:
                        start = fruit_2_last_index + 1
                        fruit_2 = tree[end]
                        fruit_2_last_index = end

        return max(best_so_far, len(tree) - start)

class Solution:
    def totalFruit(self, tree: List[int]) -> int:
        q = []
        ans = -99999999999
        s = 0
        e = s
        while e<len(tree):
            if tree[e] not in q:
                if len(q)<2:
                    q.append(tree[e])
                else:
                    if e-s > ans:
                        ans = e-s
                    i = e-1
                    while tree[i] == tree[e-1] and i>-1:
                        i -= 1
                    s = i+1
                    q.clear()
                    q.append(tree[s])
                    q.append(tree[e])

            e += 1

        if e-s > ans:
            ans = e-s

        return ans

