        tran_ptr = 0
        maxlist = []

        while True:
            scan_ptr = tran_ptr
            count = 0
            types = []

            # Scan pointer reaches the end of tree[]
            # or until finding 3rd type of fruit
            while True:
                if tree[scan_ptr] in types:
