class Solution:
    def maxPerformance(self, n: int, speed: List[int], efficiency: List[int], k: int) -> int:
        ids = [i for i in range(n)]
        ids = sorted(ids, key=lambda x: -efficiency[x])
        max_perf, heap = 0, []
        sum = 0
        for i in ids:
            if len(heap) == k:
                sum -= heappop(heap)
            heappush(heap, speed[i])
            sum += speed[i]
            max_perf = max(max_perf, sum * efficiency[i])

        return max_perf % (10 ** 9 + 7)

from heapq import *

class Solution:
    def maxPerformance(self, n: int, speed: List[int], efficiency: List[int], k: int) -> int:

        # sort by descending efficiency order
        engineers = sorted(zip(speed, efficiency), key=lambda x: -x[1])
        min_heap = []
        max_performance = 0
        curr_speed_sum = 0
        for i in range(len(engineers)):
            speed = engineers[i][0]
            efficiency = engineers[i][1]

            if len(min_heap) < k:
                curr_speed_sum += speed
                heappush(min_heap, speed)
            else:
                # already have top k-speed in heap, swap it out if found a faster speed
                if speed > min_heap[0]:
                    top_kth_speed = heappushpop(min_heap, speed)
                    curr_speed_sum -= top_kth_speed
                    curr_speed_sum += speed
                else:
                    continue

            max_performance = max(max_performance, curr_speed_sum * efficiency)

        return max_performance % (10 ** 9 + 7)

class Solution:
    def maxPerformance(self, n, speed, efficiency, k):
        teams = sorted(zip(efficiency, speed), reverse=True)
        pq = []
        max_perf = s = 0
        for i in range(n):
            heapq.heappush(pq, teams[i][1])
            s += teams[i][1]
            if i >= k:
                s -= heapq.heappop(pq)
            max_perf = max(max_perf, s * teams[i][0])
        return max_perf % (10 ** 9 + 7)

