         :type nums: List[int]
         :rtype: bool
         """
         def checkv(t,c,nums,used):
             if t==0:
                 return True
             if t<0:
                 return False
             while c<len(nums) and used[c]:
                 c=c+1
             if c>=len(nums):
                 return False
             if checkv(t-nums[c],c+1,nums,used):
                 used[c]=True
                 return True
             if checkv(t,c+1,nums,used):
                 return True
             return False
         edgel=sum(nums)
         if edgel%4!=0 or edgel==0:
             return False
         edgel=edgel/4
         nums.sort(key=lambda x:-x)
         n=len(nums)
         used=[False]*n
         for p in range(3):
             t=edgel
             if not checkv(t,0,nums,used):
                 return False
         return True

class Solution:
     def makesquare(self, nums):
         s = sum(nums)
         if not s % 4 == 0:
             return False
         l = s // 4
         from collections import Counter
         self.c = Counter(nums)
         for _ in range(4):
             n = self.f(0, sorted(self.c.elements(),reverse=True), l, ())
             if not n:
                 return False
             self.c.subtract(n)
         return True

     def f(self, index, keys, sum, nums):
         if sum == 0:
             return nums
         if sum < 0 or index >= len(keys):
             return None
         return self.f(index + 1, keys, sum - keys[index], (*nums, keys[index])) \
                or self.f(index + 1, keys, sum, nums)

class Solution:
    def maxArea(self, h: int, w: int, horizontalCuts: List[int], verticalCuts: List[int]) -> int:
        mod = int(1e9)+7
        return ( ( self.getMax(horizontalCuts, h) % mod ) * ( self.getMax(verticalCuts, w) % mod ) ) % mod

    def getMax(self, cuts, size):
        if len(cuts) == 1:
            return max(cuts[0], size - cuts[0])

        cuts.sort()

        max_cut_size = max(cuts[0], size - cuts[-1])
        for index in range(1, len(cuts)):
            if cuts[index] - cuts[index - 1] > max_cut_size:
                max_cut_size = cuts[index] - cuts[index - 1]

        return max_cut_size

class Solution:
    def maxArea(self, h: int, w: int, horizontalCuts: List[int], verticalCuts: List[int]) -> int:
        h_max = self.get_max_interval(w, sorted(verticalCuts))
        w_max = self.get_max_interval(h, sorted(horizontalCuts))
        return (h_max*w_max) % (10**9 + 7)

    def get_max_interval(self, length, cuts):
        current = 0
        max_cut = 0
        for cut in cuts:
            max_cut = max(max_cut, cut - current)
            current = cut

        max_cut = max(max_cut, length - current)
        return max_cut

class Solution:
    def maxArea(self, h: int, w: int, horizontalCuts: List[int], verticalCuts: List[int]) -> int:
        horizontalCuts.sort()
        verticalCuts.sort()

        def getGap(arr, n):
            prev=0
            i=0
            res=0
            while i<len(arr):
                res=max(arr[i]-prev, res)
                prev=arr[i]
                i+=1
            return max(n-prev, res)

        return (getGap(horizontalCuts, h)*getGap(verticalCuts, w))%(10**9 + 7)

class Solution:
    def maxJumps(self, arr: List[int], d: int) -> int:
        dp = [1] * (len(arr) + 1)
        stack = []
        for i, n in enumerate(arr + [1000000]):
            while stack and arr[stack[-1]] < n:
                same_height_idx = [stack.pop()]
                while stack and arr[stack[-1]] == arr[same_height_idx[0]]:
                    same_height_idx.append(stack.pop())
                for j in same_height_idx:
                    # jump to left
                    if i - j <= d:
                        dp[i] = max(dp[i], dp[j] + 1)
                    # jump to right
                    if stack and j - stack[-1] <= d:
                        dp[stack[-1]] = max(dp[stack[-1]], dp[j] + 1)
            stack.append(i)
        return max(dp[:-1])

class Solution: # top-down dp
    # Time complexity O(ND)
    # Space complexity O(N) for dp
    def maxJumps(self, arr: List[int], d: int) -> int:
        n = len(arr)
        dp = [1] * (n+1)
        stack = []

        for i, a in enumerate(arr + [float('inf')]):
            while stack and arr[stack[-1]] < a:
                L = [stack.pop()]
                while stack and arr[stack[-1]] == arr[L[0]]:
                    L.append(stack.pop())
                for j in L:
                    if i - j<=d:
                        dp[i] = max(dp[i], dp[j] + 1)
                    if stack and j - stack[-1] <=d:
                        dp[stack[-1]] = max(dp[stack[-1]], dp[j] + 1)
            stack.append(i)
        return max(dp[:-1])

class Solution:
    def maxJumps(self, arr: List[int], d: int) -> int:
        res = 0
        visited = {}

        def dfs(i):
            if i in visited:
                return visited[i]

            step = 1

            i_right = i + 1
            while i_right < len(arr) and i_right - i <= d:
                if arr[i_right] >= arr[i]:
                    break
                step = max(step, 1+dfs(i_right))
                i_right += 1

            i_left = i - 1
            while i_left >= 0 and i - i_left <= d:
                if arr[i_left] >= arr[i]:
                    break
                step = max(step, 1+dfs(i_left))
                i_left -= 1
            visited[i] = step
            return step


        for i in range(len(arr)):
            res = max(res, dfs(i))

        return res

