            ret = 1
            for step in range(1,d+1):
                m = i - step
                if 0 <= m < len(arr) and arr[m] < arr[i] and left:
                    ret = max(ret,f(m)+1)
                else:
                    left = False
                m = i + step
                if 0 <= m < len(arr) and arr[m] < arr[i] and right:
                    ret = max(ret,f(m)+1)
                else:
                    right = False

                if (not left) and (not right):
                    break
            cache[i] = ret
            return ret

        mm = 0
        for i in range(len(arr)):
            fi = f(i) if i not in cache else cache[i]
            mm = max(f(i),mm)

        return mm

import sys

def dp(s1, s2, i, j, mem):
    if (i, j) in mem:
        return mem[(i, j)]
    elif i >= len(s1) and j >= len(s2):
        res = ''
    elif i >= len(s1):
        res = s2[j:]
    elif j >= len(s2):
        res = s1[i:]
    else:
        if s1[i] == s2[j]:
            res = s1[i] + dp(s1, s2, i+1, j+1, mem)
        else:
            left  = s1[i] + dp(s1, s2, i+1, j, mem)
            right = s2[j] + dp(s1, s2, i, j+1, mem)

            if len(left) < len(right):
                res = left
            else:
                res = right
    mem[(i, j)] = res
    return res

