class Solution:
    def findLengthOfShortestSubarray(self, arr: List[int]) -> int:
        n = len(arr)
        if n<=1: 
            return 0
        l,r = n,-1

        for i in range(1,n):
            if arr[i]<arr[i-1]:
                l = i
                break
        # monotonicially increasing
        if l == n: return 0

        for j in range(n-2,-1,-1):
            if arr[j]>arr[j+1]:
                r = j
                break

        # you can delete all to the left of r (including r)
        # you can also delete all to the right of l (including l)
        ans = min(r+1,n-l)

        i = 0
        # sliding window, find the rightmost i for each j
        # note at all time i must be less than l
        for j in range(r+1,n):
            while i<l and arr[i] <= arr[j]:
                i += 1
            ans = min(ans,j-i)
        return ans

class Solution:
    def findLengthOfShortestSubarray(self, arr: List[int]) -> int:
        n = len(arr)
        s = 0
        e = n - 1

        while  s < (n - 1) and arr[s] <= arr[s + 1]:
            s+=1
        if(s == n - 1):
            return 0

        while e >= s and arr[e] >= arr[e - 1]:
            e-=1

        result = min(n - 1 - s, e)

        i = 0
        j = e
        while(i <= s and j < n):
            if arr[j] >= arr[i]:
                result = min(result, j - i - 1)
                i+=1
            else:
                j+=1

        return result

