class Solution:
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        n = len(s)

        def compLen(c):
            return 1 + len(str(c)) if c > 1 else 1

        @lru_cache(None)
        def dp(i, k): # return {head: (len, -head_count)}
            if (n - i) <= k:
                return {} # remove all
            x, res = s[i], {}
            # remove
            if k:
                res = dp(i + 1, k - 1)
            # keep
            keep = dp(i + 1, k)
            t = [(1 + min((leng for leng, _ in list(keep.values())), default=0), -1)]
            if x in keep:
                leng, negc = keep[x]
                leng, negc = (leng - compLen(-negc) + compLen(-negc + 1),
                              negc - 1)
                t.append((leng, negc))
            if x in res:
                t.append(res[x])
            res[x] = min(t)
            return res

        m = dp(0, k)
        return min((leng for leng, _ in list(m.values())), default = 0)

class Solution:
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        def _len(cnt): return 1 if cnt == 1 else 2 if cnt <= 9 else 3 if cnt <= 99 else 4

        @lru_cache(None)
        def solve(left, k):
            if k < 0:
                return float('inf')
            # remove s[0:left+1]
            if left + 1 == k:
                return 0
            # 1. keep s[left]
            # 2. remove s[left]
            res = min(solve(left - 1, k) + 1, solve(left - 1, k - 1))
            cnt = 1
            for j in range(left - 1, -1, -1):
                if s[j] != s[left]:
                    k -= 1
                    if k < 0:
                        break
                else:
                    cnt += 1
                    if j < k:
                        break
                    res = min(res, solve(j - 1, k) + _len(cnt)) 
            return res
        return solve(len(s) - 1, k)

from typing import *
from functools import lru_cache



class Solution:
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:

        def get_compressed_len(n):
            if n == 0:
                return 0
            if n == 1:
                return 1
            return len(str(n)) + 1

        @lru_cache(None)
        def dp_memo(x, y, left_count, remain_k):
            if x > y:
                return 0

            # 1. don't concat s[x] with any further character
            ans = get_compressed_len(left_count + 1) + dp_memo(x + 1, y, 0, remain_k)

            # 2. remove s[x]
            if remain_k > 0:
                ans = min(ans, get_compressed_len(left_count) + dp_memo(x + 1, y, 0, remain_k - 1))

            # 3. try to concat s[x] with further character s[xx]
            for i in range(remain_k + 1):
                xx = x + i + 1
                if xx > y:  # out of bounds
                    break
                if s[x] == s[xx]:  # same s[x] and s[xx], concat them
                    ans = min(ans, dp_memo(xx, y, left_count + 1, remain_k - i))

            # print(x, y, left_count, remain_k, '->', ans)
            return ans
        return dp_memo(0, len(s) - 1, 0, k)

class Solution:    
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        n = len(s)
        dp = [[n if i > 0 else 0] * (k + 1) for i in range(n + 1)]

        def cost(v):
            return (1 + len(str(v))) if v > 1 else v

        for i in range(n):
            for j in range(k + 1):
                if j:
                    dp[i + 1][j - 1] = min(dp[i + 1][j - 1], dp[i][j])
                take = 0
                for x in range(i + 1)[::-1]:
                    if s[x] != s[i]:
                        take += 1
                    if take > j:
                        break
                    dp[i + 1][j - take] = min(dp[i + 1][j - take], dp[x][j] + cost(i - x - take + 1))        
        return min(dp[n])

class Solution:
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        states = { # (deletions, last character, multiple) -> minimum length
            (0, None, 0): 0
        } 

        def count_len(d):
            if d == 0 or d == 1:
                return 0
            else:
                return len(str(d))

        for c in s:
            new_states = collections.defaultdict(lambda: float('inf'))
            for (deletions, last_char, count), length in states.items():
                # with deletion
                if deletions < k:
                    new_state = (deletions + 1, last_char, count)
                    new_length = length
                    new_states[new_state] = min(new_states[new_state], new_length)
                # without deletion
                if c == last_char:
                    new_state = (deletions, c, count + 1)
                    new_length = length - count_len(count) + count_len(count + 1)
                else:
                    new_state = (deletions, c, 1)
                    new_length = length + 1
                new_states[new_state] = min(new_states[new_state], new_length)
            states = new_states

        min_length = float('inf')
        for (deletions, last_char, count), length in states.items():
            if deletions == k:
                min_length = min(min_length, length)
        return min_length

class Solution:
    def minRefuelStops(self, target: int, startFuel: int, stations: List[List[int]]) -> int:
        if startFuel >= target:
            return 0
        if not stations:
            return -1

        fdelta = startFuel-stations[0][0]
        if fdelta < 0:
            return -1

        curr = [fdelta + stations[0][1], fdelta]

        for i, sta in enumerate(stations[1:]):
            treck = sta[0] - stations[i][0]
            leftover = curr[0]-treck
            if leftover < 0:
                return -1
            nex = [leftover + sta[1], leftover]
            for j, f in enumerate(curr[1:]):
                leftover = curr[j+1] - treck
                if leftover < 0:
                    break
                else:
                    nex[-1] = max(nex[-1], leftover+sta[1])
                    nex.append(leftover)

            curr = nex

        leftover = target - stations[-1][0]

        while curr and curr[-1] < leftover:
            curr.pop()

        return len(stations) - len(curr) + 1 if curr else -1

class Solution:
    def minRefuelStops(self, target: int, startFuel: int, stations: List[List[int]]) -> int:
        if startFuel >= target:
            return 0
        n = len(stations)
        dp = [0]*(n+1)
        dp[0] = startFuel


        for i in range(1, n+1):
            for j in range(i, 0, -1):
                if dp[j-1] >= stations[i-1][0]:
                    # use station i-1
                    dp[j] = max(dp[j], dp[j-1] + stations[i-1][1])

        for i in range(1, n+1):
            if dp[i] >= target:
                return i
        return -1

import heapq
class Solution:
    def minRefuelStops(self, target: int, startFuel: int, stations: List[List[int]]) -> int:
        point=0
        level=0
        gas=startFuel
        if gas>=target:
            return level
        heap=[]
        stations.append([target+1,float('inf')])
        for pos,gas_add in stations:
            if gas>=pos:
                heapq.heappush(heap,-gas_add)
            else:
                while heap:
                    gasmin=heapq.heappop(heap)
                    gas-=gasmin
                    level+=1
                    if gas>=target:
                        return level
                    if gas>=pos:
                        heapq.heappush(heap,-gas_add)
                        break
        return -1

class Solution:
     def maxProfit(self, prices):
         """
         :type prices: List[int]
         :rtype: int
         """
         if not prices:
             return 0
         sell = hold = 0
         buy = -prices[0]

