         :rtype: int
         """
         if prices is None or len(prices) == 0:
             return 0 
         # 0 for buy 1 for sell 2 for break
         dp = [[-9999999]*len(prices) for _ in range(3)]
         dp[0][0], dp[1][0], dp[2][0] = -prices[0], 0, 0
