class Solution:
    def atMostNGivenDigitSet(self, digits: List[str], n: int) -> int:

        count = 0
        length = 1
        n_str = str(n)
        while length < len(n_str):
            count+= len(digits)**length
            length+=1

        digits_sorted = sorted(digits)


        ## now length should equal to len(n), we compare the number with same length
        current_digit = 0
        while current_digit < length:
            for digit in digits_sorted:
                next_round = False
                if digit < n_str[current_digit]:
                    count+=len(digits)**(length-current_digit-1)
                elif digit > n_str[current_digit]:
                    return count
                else:
                    if current_digit == length-1:
                        return count+1
                    else: 
                        current_digit+=1
                        next_round = True
                        break
            if not next_round:
                return count

        return count

class Solution:
    def atMostNGivenDigitSet(self, digits: List[str], n: int) -> int:
        ns = str(n)
        dp = 1
        digits.sort()
        M, N = len(ns), len(digits)

        for i in range(M-1, -1, -1):
            dp2 = 0

            for d in digits:
                if d>ns[i]: break
                if d<ns[i]:
                    dp2 += N**(M-1-i)
                else:
                    dp2 += dp

            dp = dp2
        return dp + sum(N**i for i in range(1, M))

class Solution:
    def atMostNGivenDigitSet(self, digits: List[str], n: int) -> int:
        def less(digits, d):
            return len([i for i in digits if i < d ])

        cnt = 0
        ld, ln = len(digits), len(str(n))
        N = str(n)
        for i in range(ln-1):
            cnt += ld ** (i+1)
        for i in range(ln):
            cnt += less(digits, N[i]) * (ld ** (ln - i -1) )
            if N[i] not in digits:
                return cnt
        return cnt + 1

