             mid = (low+high)//2
             if nums[mid] > nums[high]:
                 low = mid+1
             else:
                 high = mid
         start = low
         low, high = 0, len(nums)-1
         while low <= high:
             mid = (low+high)//2
             realMid = (mid+start) % (len(nums))
             if nums[realMid] == target:
                 return realMid
             if target > nums[realMid]:
                 low = mid+1
             else:
                 high = mid-1
         return -1

class Solution:
     def Greedy(self, counts, zeros, ones) :
         num = 0;
         for a, b in counts :
             if a <= zeros and b <= ones :
                 zeros -= a
                 ones -= b
                 num += 1
         return num

     def findMaxForm(self, strs, m, n):
         """
         :type strs: List[str]
         :type m: int
         :type n: int
         :rtype: int
         """
         counts = list(map(lambda x : [x.count('0'), x.count('1')], strs))
         return max(self.Greedy(sorted(counts, key = lambda c : min(c[0], c[1])), m, n),
                    self.Greedy(sorted(counts, key = lambda c : min(m - c[0], n - c[1]), reverse = True), m, n))

