     def eliminateSenators(self,r,d):
         if len(r)==0: return "Dire"
         if len(d)==0:return "Radiant"

         r2 = collections.deque()
         d2 = collections.deque()

         while len(r)> 0 or len(d)>0:
             if len(r)==0:
                 if len(r2)==0:
                     return "Dire"
                 else:
                     r2.popleft()
                     d2.append(d.popleft())
             elif len(d)==0:
                 if len(d2)==0:
                     return "Radiant"
                 else:
                     d2.popleft()
                     r2.append(r.popleft())       
             else:
                 r_curr = r.popleft()
                 d_curr = d.popleft()
                 if r_curr < d_curr:
                     r2.append(r_curr)
                 else:
                     d2.append(d_curr)

         return self.eliminateSenators(r2,d2)

class Solution:
    def mergeStones(self, stones: List[int], K: int) -> int:
        n = len(stones)
        if (n - 1) % (K - 1) != 0:
            return -1
        prefix = [0]
        for s in stones:
            prefix.append(prefix[-1] + s)
        @lru_cache(None)
        def dp(i, j):
            if j - i + 1 < K:
                return 0
            res = 0
            if (j - i) % (K - 1) == 0:
                res = prefix[j+1] - prefix[i]
            return res + min(dp(i, mid) + dp(mid+1, j) for mid in range(i, j, K - 1))
        return dp(0, n - 1)

class Solution:
    def mergeStones(self, stones: List[int], K: int) -> int:
        n = len(stones)
        if (n-1)%(K-1) != 0:
            return -1
        dp = [[0]*n for _ in range(n)]
        sums = [0]*(n+1)
        for i in range(1,n+1):
            sums[i] = sums[i-1]+stones[i-1]
        for length in range(K,n+1):
            for i in range(n-length+1):
                j = i+length-1
                dp[i][j] = float('inf')
                for t in range(i,j,K-1):
                    dp[i][j] = min(dp[i][j], dp[i][t]+dp[t+1][j])
                if (j-i)%(K-1)==0:
                    dp[i][j] += sums[j+1]-sums[i]
        return dp[0][n-1]

