class Solution:
    def longestDupSubstring(self, S):
        nums, N = [ord(c) - ord('a') for c in S], len(S)
        BASE, MOD = 26, 2**32
        def check(L):
            cur_hash, seen = 0, set()
            for val in nums[:L]:
                cur_hash = (cur_hash * BASE + val) % MOD
            seen.add(cur_hash)
            X = pow(BASE, L-1, MOD)
            for idx, val in enumerate(nums[L:]):
                cur_hash -= nums[idx] * X
                cur_hash = (cur_hash * BASE + val) % MOD
                if cur_hash in seen:
                    return idx + 1
                seen.add(cur_hash)
            return -1
        low, high = 1, N + 1
        start = 0
        while low < high:
            mid = (low + high)//2
            idx = check(mid)
            if idx != -1:
                low = mid + 1
                start = idx
            else:
                high = mid
        return S[start: start + low - 1]

class Solution:
    def longestDupSubstring(self, S: str) -> str:

        def has_duplicate(m, S):
            val, Mod = 0, 2**63-1
            for i in range(m):
                val = (26*val + ord(S[i])) % Mod

            d = set([val])
            const = 26**m % Mod
            for i in range(m, len(S)):
                val = (26*val + ord(S[i]) - ord(S[i-m])*const) % Mod
                if val in d: return i-m+1
                d.add(val)
            return -1

        l, r = 0, len(S)
        start, length = -1, 0
        while l<=r:
            mid = l + (r-l)//2
            idx = has_duplicate(mid, S)
            if idx!=-1:
                l = mid + 1
                start, length = idx, mid
            else:
                r = mid - 1

        if start==-1: return ''
        return S[start:start+length]

