class Solution:
    def pushDominoes(self, dominoes: str) -> str:
        n = len(dominoes)
        d1 = [-1] * n
        d2 = [-1] * n

        cnt = INF
        for i in range(n - 1, -1, -1):
            if dominoes[i] == 'L':
                cnt = 0
            elif dominoes[i] == '.':
                cnt += 1
            elif dominoes[i] == 'R':
                cnt = INF
            d1[i] = cnt

