         :rtype: int
         """
         minSet = set()
         maxSet = set()
         nums = set(nums)
         for num in nums:

             if num > 0:
                 if num + 1 in minSet:
                     minSet.remove(num + 1)
                     minSet.add(num)
                     if num - 1 in maxSet:
