class Solution:
    def regionsBySlashes(self, grid):
        grid = self.convert_grid(grid)
        print(*(list(map(str, x)) for x in grid), sep='\
')
        return len([self.destroy_island(x, y, grid) for y in range(len(grid)) for x,v in enumerate(grid[y]) if v == 0])

    @staticmethod
    def convert_grid(grid):
        new_grid = [[0] * len(grid[0]) * 2 for _ in range(len(grid) * 2)]
        for (x, y, v) in ((x, y, v) for y in range(len(grid)) for x,v in enumerate(grid[y]) if v in '\\\\/'):
            new_grid[y * 2 + 0][x * 2 + (1 if v == '/' else 0)] = v
            new_grid[y * 2 + 1][x * 2 + (0 if v == '/' else 1)] = v
        return new_grid

    def destroy_island(self, x, y, grid):
        grid[y][x] = 1
        for c in Solution.search(x, y, grid):
            self.destroy_island(c[0], c[1], grid)

    @staticmethod
    def search(x, y, grid):
        in_bounds = lambda c:0 <= c[1] < len(grid) and 0 <= c[0] < len(grid[c[1]])
        check_orthog = lambda c:in_bounds(c) and grid[c[1]][c[0]] == 0
        def check_diag(c):
            if not in_bounds(c) or grid[c[1]][c[0]] != 0: return False
            d_x, d_y = c[0] - x, c[1] - y
            sep = '\\\\' if ((d_x > 0 > d_y) or (d_x < 0 < d_y)) else '/'
            return not (grid[y + d_y][x] == sep and grid[y][x + d_x] == sep)
        yield from chain(filter(check_orthog, ((x-1, y), (x+1, y), (x, y-1), (x, y+1))),
                         filter(check_diag, ((x + 1, y + 1), (x + 1, y - 1), (x - 1, y + 1), (x - 1, y - 1))))

class DSU:
    def __init__(self):
        self.parent = {}

    def find(self, x):
        if x not in self.parent:
            self.parent[x] = x
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])

        return self.parent[x]

    def union(self, x, y):
        xroot, yroot = self.find(x), self.find(y)
        if xroot != yroot:
            self.parent[yroot] = xroot

class Solution:
    def regionsBySlashes(self, grid: List[str]) -> int:
        n = len(grid)
        dsu = DSU()

        for i in range(n):
            for j in range(n):
                if i > 0:
                    dsu.union((i - 1, j, 2), (i, j, 0))
                if j > 0:
                    dsu.union((i, j - 1, 1), (i, j, 3))
                if grid[i][j] != '/':
                    dsu.union((i, j, 0), (i, j, 1))
                    dsu.union((i, j, 2), (i, j, 3))
                if grid[i][j] != '\\\\':
                    dsu.union((i, j, 3), (i, j, 0))
                    dsu.union((i, j, 1), (i, j, 2))

        seen = set()
        for key in dsu.parent.keys():
            temp = dsu.find(key)
            seen.add(temp)

        return len(seen)

from typing import List

class DS:

    def __init__(self, n):
        self.sizes = [1] * n
        self.roots = [i for i in range(n)]

    def query(self, x):
        root = x
        while root != self.roots[root]:
            self.roots[root] = self.roots[self.roots[root]]
            root = self.roots[root]
        return root

    def union(self, x, y):
        xRoot, yRoot = self.query(x), self.query(y)
        s, l = (xRoot, yRoot) if self.sizes[xRoot] < self.sizes[yRoot] else (yRoot, xRoot)
        self.roots[s] = l
        self.sizes[l] += self.sizes[s] 

class Solution:
    def regionsBySlashes(self, grid: List[str]) -> int:
        n = len(grid)
        nodes = DS(4 * n * n)
        getIndex = lambda r, c, k: 4 * (n * r + c) + k
        for i in range(n):
            for j in range(n):
                if i > 0: nodes.union(getIndex(i, j, 0), getIndex(i - 1, j, 2))
                if i < n - 1: nodes.union(getIndex(i, j, 2), getIndex(i + 1, j, 0))
                if j > 0: nodes.union(getIndex(i, j, 3), getIndex(i, j - 1, 1))
                if j < n - 1: nodes.union(getIndex(i, j, 1), getIndex(i, j + 1, 3))
                if grid[i][j] != '/':
                    nodes.union(getIndex(i, j, 0), getIndex(i, j, 1))
                    nodes.union(getIndex(i, j, 3), getIndex(i, j, 2))
                if grid[i][j] != '\\\\':
                    nodes.union(getIndex(i, j, 0), getIndex(i, j, 3))
                    nodes.union(getIndex(i, j, 1), getIndex(i, j, 2))
        return sum(i == nodes.query(i) for i in range(4 * n * n))

