class Solution:
     def frequencySort(self, s):
         """
         :type s: str
         :rtype: str
         """
         counter = {}
         for c in s:
             if c in counter:
                 counter[c] += 1
             else:
                 counter[c] = 1

         res = ""
         while counter:
             m = max(counter, key=counter.get)
             res += m * counter[m]
             del counter[m]
         return res

class Solution:
     def frequencySort(self, s):
         """
         :type s: str
         :rtype: str
         """
         mapping = {}
         for c in s:
             mapping[c] = mapping[c] + 1 if c in mapping else 1
         bucket = [[] for _ in range(len(s) + 1)]
         for c, freq in mapping.items():
             bucket[freq].append(c)
         res = ""
         for i in range(len(s), -1, -1):
             for c in bucket[i]:
                 for _ in range(i):
                     res += c
         return res

class Solution:
    def move(self, pos, direction):
        x, y = pos
        if direction == 0:
            y += 1
        elif direction == 1:
            x += 1
        elif direction == 2:
            y -= 1
        elif direction == 3:
            x -= 1
        return (x, y)

    def isRobotBounded(self, instructions: str) -> bool:
        direction = 0 # 0 for north, 1 for east, 2 for south, 3 for west
        pos = (0, 0)
        for i in instructions:
            if i == 'G':
                pos = self.move(pos, direction)
            elif i == 'L':
                direction = (direction - 1) % 4
            elif i == 'R':
                direction = (direction + 1) % 4
        if pos == (0, 0) or direction != 0:
            return True
        else:
            return False

class Solution:
    def isRobotBounded(self, instructions: str) -> bool:


        mapping = {0: [1, 0], 1: [0, 1], 2: [-1, 0], 3: [0, -1]}

        direction = 0
        current = [0, 0]

        for instr in instructions:
            if instr == 'L':
                direction -= 1
            elif instr == 'R':
                direction += 1
            elif instr == 'G':
                move = mapping[direction]

                current[0] += move[0]
                current[1] += move[1]

            direction %= 4

        if current == [0, 0] or direction != 0:
            return True
        return False

class Solution:
    def isRobotBounded(self, instructions: str) -> bool:
        x, y, dx, dy = 0, 0, 0, 1
        for i in instructions:
            if i == 'R': dx, dy = dy, -dx
            if i == 'L': dx, dy = -dy, dx
            if i == 'G': x, y = x + dx, y + dy
        return (x, y) == (0, 0) or (dx, dy) != (0,1)

class Solution:
    def isRobotBounded(self, instructions: str) -> bool:
        move = {'N':(0,1), 'S':(0,-1), 'E':(1,0), 'W':(-1,0)}
        right = {'N':'E', 'S':'W', 'E':'S', 'W':'N'}
        left = {'N':'W', 'S':'E', 'E':'N', 'W':'S'}

        pos = (0,0)
        dire = 'N'

        for c in instructions:
            if c=='G':
                x, y = pos
                dx, dy = move[dire]
                pos = (x+dx, y+dy)
            elif c=='L':
                dire = left[dire]
            else:
                dire = right[dire]

        return pos==(0,0) or dire!='N'

class Solution:
    def maxEqualFreq(self, A: List[int]) -> int:
        n = len(A)
        count = collections.defaultdict(int)
        freq = collections.defaultdict(int)
        for i in range(n):
            count[A[i]] +=1
            freq[count[A[i]]]+=1

        for i in range(n-1, 0, -1):
            # If include A[i]
            if count[A[i]] * freq[count[A[i]]] == i:
                return i + 1
            freq[count[A[i]]] -= 1
            count[A[i]] -= 1
            if count[A[i-1]] * freq[count[A[i-1]]] == i:
                return i + 1

        return 1

class Solution:
