class Solution:
    def minSumOfLengths(self, arr: List[int], target: int) -> int:
        if not arr:
            return -1

        def getMinSub(arr, target):
            dp = [float('inf')]*len(arr)
            total = 0
            lookup = defaultdict(int)
            for index, val in enumerate(arr):
                total += val
                if total == target:
                    dp[index] = index - 0 + 1
                elif total - target in lookup:
                    dp[index] = min(index - lookup[total-target] + 1, dp[index-1])
                else:
                    dp[index] = dp[index-1]

                lookup[total] = index + 1
            return dp 

        forward = getMinSub(arr, target)
        backward = getMinSub(arr[::-1], target)[::-1]

        minresult = float('inf')
        for i in range(1,len(arr)):
            minresult = min(minresult,forward[i-1]+ backward[i])

        return minresult if minresult != float('inf') else -1

class Solution:
    def minSumOfLengths(self, arr: List[int], target: int) -> int:
        prefix = {0: -1}
        best_till = [math.inf] * len(arr)
        ans = best = math.inf
        for i, curr in enumerate(itertools.accumulate(arr)):
            if curr - target in prefix:
                end = prefix[curr - target]
                if end > -1:
                    ans = min(ans, i - end + best_till[end])
                best = min(best, i - end)
            best_till[i] = best
            prefix[curr] = i
        return -1 if ans == math.inf else ans

class Solution:
    def minSumOfLengths(self, arr: List[int], target: int) -> int:
        # prefix[i] is the min len of subarray with sum in arr[:i]
        # suffix[i] is the min len of subarray with sum in arr[i:]
        prefix, suffix = [float('inf')] * len(arr), [float('inf')] * len(arr)
        curSum, l = 0, 0
        for r in range(1, len(arr)):
            prefix[r] = prefix[r - 1]
            curSum += arr[r - 1]
            while curSum >= target:
                if curSum == target:
                    prefix[r] = min(prefix[r], r - l)
                curSum -= arr[l]
                l += 1
        curSum, r = 0, len(arr)
        for l in range(len(arr) - 1, 0, -1):
            if l < len(arr) - 1:
                suffix[l] = suffix[l + 1]
            curSum += arr[l]
            while curSum >= target:
                if curSum == target:
                    suffix[l] = min(suffix[l], r - l)
                curSum -= arr[r - 1]
                r -= 1

        res = len(arr) + 1
        for i in range(1, len(arr) - 1):
            res = min(res, prefix[i] + suffix[i])
        return res if res <= len(arr) else -1

class Solution:
    def containsCycle(self, grid: List[List[str]]) -> bool:
        n = len(grid)
        m = len(grid[0])

        F = [i for i in range(m * n)]
        def find(x):
            if x == F[x]:
                return x
            else:
                F[x] = find(F[x])
                return F[x]

        for i in range(n):
            for j in range(m):
                if i > 0 and grid[i-1][j] == grid[i][j]:
                    f1 = find((i-1)*m+j)
                    f2 = find((i)*m+j)
                    if f1 == f2:
                        return True
                    F[f1] = f2
                if j > 0 and grid[i][j-1] == grid[i][j]:
                    f1 = find((i)*m+j-1)
                    f2 = find((i)*m+j)
                    if f1 == f2:
                        return True
                    F[f1] = f2
        return False

class Solution:
    def containsCycle(self, grid: List[List[str]]) -> bool:
        visited = set()
        m = len(grid)
        if m==1: return False
        n = len(grid[0])
        dirs = [(0,-1),(-1,0),(0,1),(1,0)]
        def dfs(prev, curr):
            if curr in visited: return True
            visited.add(curr)
            for dirn in dirs:
                nei = (dirn[0]+curr[0], dirn[1]+curr[1])
                if 0<=nei[0]<m and 0<=nei[1]<n and nei != prev and grid[nei[0]][nei[1]] == grid[curr[0]][curr[1]]:
                    if dfs(curr, nei): return True
            return False
        for i in range(m):
            for j in range(n):
                if (i,j) not in visited:
                    if dfs(None, (i,j)): return True
        return False

import collections
class Solution:
    def containsCycle(self, grid: List[List[str]]) -> bool:
        def find(pos):
            if parents[pos] != pos:
                parents[pos] = find(parents[pos])
            return parents[pos]

        def union(pos1, pos2):
            parent1, parent2 = find(pos1), find(pos2)
            if parent1 != parent2:
                if ranks[parent2] > ranks[parent1]:
                    parents[parent1] = parent2
                else:
                    parents[parent2] = parent1
                    if ranks[parent1] == ranks[parent2]:
                        ranks[parent1] += 1

        rows, cols = len(grid), len(grid[0])
        parents = {(i, j): (i, j) for i in range(rows) for j in range(cols)}
        ranks = collections.Counter()
        for i, row in enumerate(grid):
            for j, letter in enumerate(row):
                if i > 0 and j > 0 and grid[i-1][j] == grid[i][j-1] == letter and find((i-1, j)) == find((i, j-1)):
                    return True
                for r, c in (i - 1, j), (i, j - 1):
                    if 0 <= r < rows and 0 <= c < cols and grid[r][c] == letter:
                        union((i, j), (r, c))
        return False

class Solution:
    def containsCycle(self, grid: List[List[str]]) -> bool:
        def find(pos):
            if parents[pos] != pos:
                parents[pos] = find(parents[pos])
            return parents[pos]

        def union(pos1, pos2):
            parent1, parent2 = find(pos1), find(pos2)
            if parent1 != parent2:
                if ranks[parent2] > ranks[parent1]:
                    parents[parent1] = parent2
                else:
                    parents[parent2] = parent1
                    if ranks[parent1] == ranks[parent2]:
                        ranks[parent1] += 1

        rows, cols = len(grid), len(grid[0])
        parents = {(i, j): (i, j) for i in range(rows) for j in range(cols)}
        ranks = collections.Counter()
        for i, row in enumerate(grid):
            for j, letter in enumerate(row):
                if i > 0 and j > 0 and grid[i-1][j] == grid[i][j-1] == letter and find((i-1, j)) == find((i, j-1)):
                    return True
                for r, c in (i - 1, j), (i, j - 1):
                    if 0 <= r < rows and 0 <= c < cols and grid[r][c] == letter:
                        union((i, j), (r, c))
        return False

class UnionFind:
    def __init__(self,n):
        self.parent = [i for i in range(n)]
        self.size = [1]*n
    def find(self,A):
        root=A
        while root!=self.parent[root]:
            root=self.parent[root]

        while A!=root:
            old_parent=self.parent[A]
            self.parent[A]=root
            A=old_parent
        return(root)

    def union(self,A,B):
        root_A = self.find(A)
        root_B = self.find(B)
        if root_A==root_B:
            return(False)

        if self.size[root_A]<self.size[root_B]:
            self.parent[root_A]=root_B
            self.size[root_B]+=self.size[root_A]
        else:
            self.parent[root_B]=root_A
            self.size[root_A]+=self.size[root_B]

        return(True)
class Solution:
    def containsCycle(self, grid: List[List[str]]) -> bool:
        R = len(grid) ; C = len(grid[0])
        dsu = UnionFind(R*C)
        def encode(r,c):
            return(r*C+c)

        for r in range(R):
            for c in range(C):
                if c+1<C and grid[r][c]==grid[r][c+1]:
                    if not dsu.union( encode(r,c),encode(r,c+1) ):
                        return(True)
                if r+1<R and grid[r][c]==grid[r+1][c]:
                    if not dsu.union( encode(r,c),encode(r+1,c) ):
                        return(True)

        return(False)

class Solution:
    def numMagicSquaresInside(self, grid: List[List[int]]) -> int:
        # slide window and call isMagicSquare
        if len(grid) < 3 or len(grid[0]) < 3:
            return 0
        rows = len(grid)
        cols = len(grid[0])
        magic_squares = 0
        for i in range(rows - 2):
            for j in range(cols - 2):
                window = [tmp[j:j + 3] for tmp in grid[i: i + 3]]
                if self.isMagicSquare(window):
                    magic_squares += 1

        return magic_squares

    def isMagicSquare(self, square: List[List[int]]) -> bool:
        target = square[0][0] + square[0][1] + square[0][2]
        seen = {}
        print(square)
        # check rows
        for row in square:
            tmp = 0
            for i in row:
                tmp += i
                if i in seen or i > 9 or i < 1:
                    return False
                else:
                    seen[i] = 1
            if tmp != target:
                return False

        # check cols
        for i in range(3):
            tmp = 0
            for row in square:
                tmp += row[i]

            if tmp != target:
                return False


        # check left to right diag
        tmp = 0
        for i in range(3):
            tmp += square[i][i]
        if tmp != target:
            return False

        # check right to left diag
        tmp = 0
        for i in range(3):
            tmp += square[i][2 - i]
        if tmp != target:
            return False

        return True

