    def maxProbability(self, n: int, edges: List[List[int]], probs: List[float], s: int, t: int) -> float:
        # first build the graph
        graph = {u: {} for u in range(n)}
        for (u, v), prob in zip(edges, probs):
            graph[u][v] = prob
            graph[v][u] = prob

        # run A* search
        frontier = [(-1, s)]
        seen = set()

        while len(frontier) != 0:
            neg_path_prob, u = heapq.heappop(frontier)
            if u == t:
                return -neg_path_prob

            seen.add(u)
            for v, edge_prob in graph[u].items():
                if v not in seen:
                    heapq.heappush(frontier, (neg_path_prob * edge_prob, v))
        return 0

class Solution:
    def maxProbability(self, n: int, edges: List[List[int]], succProb: List[float], start: int, end: int) -> float:
        graph = collections.defaultdict(dict)
        for edge, prob in zip(edges, succProb):
            s, t = edge
            graph[s][t] = prob
            graph[t][s] = prob

        heap = [(-1, start)]
        prob = [0] * n
        prob[start] = 1
        visited = [False] * n

        while heap:
            curr_prob, node = heapq.heappop(heap)
            if visited[node]:
                continue
            if node == end:
                return prob[end]
            curr_prob *= -1
            visited[node] = True
            for neighbor in graph[node]:
                if visited[neighbor]:
                    continue
                p = curr_prob * graph[node][neighbor]
                if p > prob[neighbor]:
                    prob[neighbor] = p
                    heapq.heappush(heap, (-p, neighbor))

        return prob[end]

class Solution:
    def maxProbability(self, n: int, edges: List[List[int]], succProb: List[float], start: int, end: int) -> float:
        weights = list(map(lambda x:-math.log2(x), succProb))
        g = defaultdict(list)
        for (u, v), w in zip(edges, weights):
            g[u].append([v, w])
            g[v].append([u, w])
        dist = {}
        q = [(0, start)]
        while q:
            w, u = heapq.heappop(q)
            if u in dist:
                continue
            dist[u] = w
            if u == end:
                break
            for v, w in g[u]:
                if v not in dist or dist[v] > dist[u] + w:
                    heapq.heappush(q, (dist[u] + w, v))
        return 2 ** (-dist[end]) if end in dist else 0.0

