class Solution:
    def __init__(self):
        self.happy_string = ''

    def getHappyString(self, n: int, k: int) -> str:
        # determine starting character
        poss_per_group = 2 ** (n - 1)
        group_num = math.ceil(k / poss_per_group) - 1
        starting_char = ''

        # check to make sure there are at least k happy strings
        if k > poss_per_group * 3:
            return ''

        if group_num == 0:
            self.happy_string += 'a'
        elif group_num == 1:
            self.happy_string += 'b'
        else:
            self.happy_string += 'c'

        self.findNextChar(group_num, n - 1, group_num * poss_per_group, (group_num + 1) * poss_per_group, k)
        return self.happy_string

    def findNextChar(self, char_index: int, n: int, start: int, end: int, k: int) -> None:
        if n != 0:
            lower_index = -1
            upper_index = -1

            # 0 = 'a', 1 = 'b', 2 = 'c'
            if char_index == 0:
                lower_index = 1
                upper_index = 2
            elif char_index == 1:
                lower_index = 0
                upper_index = 2
            else:
                lower_index = 0
                upper_index = 1

            midpoint = int((start + end ) / 2)
            if (k <= midpoint):
                self.happy_string += self.indexToStr(lower_index)
                self.findNextChar(lower_index, n - 1, start, midpoint, k)
            else:
                self.happy_string += self.indexToStr(upper_index)
                self.findNextChar(upper_index, n - 1, midpoint, end, k)                

    def indexToStr(self, index: int) -> str:
        if index == 0:
            return 'a'
        elif index == 1:
            return 'b'
        else:
            return 'c'

class Solution:
    def getHappyString(self, n: int, k: int) -> str:
        m_vals = 3 * (2 ** (n - 1))
        if k > m_vals:
            return ''
        k -= 1
        m_vals //= 3
        vals = ['a', 'b', 'c']
        mapping = {0:'a',1:'b',2:'c'}
        s = mapping[k // m_vals]
        k %= m_vals
        m_vals //= 2
        prev_map = {'a':{0:'b',1:'c'},'b':{0:'a',1:'c'},'c':{0:'a',1:'b'}}
        while m_vals:
            mapping = prev_map[s[-1]]
            s += mapping[k // m_vals]
            k %= m_vals
            m_vals //= 2
        return s

class Solution:
    def getHappyString(self, n: int, k: int) -> str:
        cnt = 0
        choice = ['a','b','c']
        ret = []
        def backTrack(lastCh, idx, l):
            nonlocal cnt, ret
            if idx == n:
                cnt += 1
                if cnt == k:
                    ret = l
                    return True
                return False
            for ch in choice:
                if ch == lastCh:
                    continue
                l.append(ch)
                if backTrack(ch, idx+1, l):
                    return True
                l.pop()               
        backTrack('x', 0, [])
        return ''.join(ret)

class Solution:
    def getHappyString(self, n: int, k: int) -> str:
        nextLetter = {'a':'bc','b':'ac','c':'ab'}
        q = deque(['a','b','c'])
        while len(q[0]) != n:
            u = q.popleft()
            for v in nextLetter[u[-1]]:
                q.append(u + v)
        return q[k - 1] if len(q) >= k else ''

