class Solution:
    def maxCandies(self, status: List[int], candies: List[int], keys: List[List[int]], containedBoxes: List[List[int]], initialBoxes: List[int]) -> int:
        # nested boxes
        reachable=[False]*len(status)
        visited=[False]*len(status)
        for box in initialBoxes:
            reachable[box]=True
        for i in range(len(containedBoxes)):
            for inside in containedBoxes[i]:
                reachable[inside]=False
        # we only start with initial boxes
        queue=initialBoxes
        target=[]
        ret=0
        while queue:
            for box in queue:
                if status[box]==1 and reachable[box] and not visited[box]:
                    ret+=candies[box]
                    visited[box]=True
                    for key in keys[box]:
                        if status[key]==0:
                            status[key]=1
                            if reachable[key]:
                                target.append(key)
                    for inside in containedBoxes[box]:
                        reachable[inside]=True
                        if status[inside]==1:
                            target.append(inside)
                else:
                    target.append(box)
            if target==queue:
                break
            queue=target
            target=[]
        return ret

from collections import deque
class Solution:
    def maxCandies(self, status: List[int], candies: List[int], keys: List[List[int]], containedBoxes: List[List[int]], initialBoxes: List[int]) -> int:

        q = deque(initialBoxes)
        visited = set()
        res = 0
        while q:
            itr, opened = len(q), False  # To detect cycle
            opened = False
            while (itr):
                itr -= 1
                v = q.popleft()
                if status[v]: # Open box, (key is available or is open)

                    opened = True
                    res += candies[v]
                    visited.add(v)

                    for x in keys[v]:
                        status[x] = 1

                    for x in containedBoxes[v]:
                        if x not in visited:
                            q.append(x)

                elif v not in visited: # Open when key is available
                    q.append(v)
            if not opened:
                return res  # Exit cycle detected
        return res

class Solution:
    def maxCandies(self, status: List[int], candies: List[int], keys: List[List[int]], containedBoxes: List[List[int]], initialBoxes: List[int]) -> int:
        reachable = [False for _ in status]
        for i in initialBoxes:
            reachable[i] = True
        can_open = [val == 1 for val in status]
        nodes_to_visit = [b for b in range(len(status)) if reachable[b] and can_open[b]]
        total_candies = 0
        while len(nodes_to_visit) >= 1:
            curr_node = nodes_to_visit[0]
            nodes_to_visit = nodes_to_visit[1:]
            total_candies += candies[curr_node]
            for k in keys[curr_node]:
                if not can_open[k] and reachable[k]:
                    nodes_to_visit.append(k)
                can_open[k] = True
            for b in containedBoxes[curr_node]:
                if not reachable[b] and can_open[b]:
                    nodes_to_visit.append(b)
                reachable[b] = True
        return total_candies

class Solution:
    def maxCandies(self, status: List[int], candies: List[int], keys: List[List[int]], containedBoxes: List[List[int]], initialBoxes: List[int]) -> int:

        stack = deque(initialBoxes)
        seen = set()        
        kseen = set()
        while stack:
            for _ in range(len(stack)):
                box = stack.popleft()
                seen.add(box)
                for key in keys[box]:
                    status[key] = 1
                for tbox in containedBoxes[box]:
                    if tbox not in seen:
                        stack.append(tbox)
        res = 0
        for box in seen:
            if candies[box] and status[box]:
                res += candies[box]
        return res

class Solution:
    def maxCandies(self, status: List[int], candies: List[int], keys: List[List[int]], containedBoxes: List[List[int]], initialBoxes: List[int]) -> int:
        n = len(status)
        visited = [0] * n
        unopened = [0] * n
        opened = []

        ans = 0
        for b in initialBoxes:
            if status[b] == 1:
                opened.append(b)
                visited[b] = 1
            else:
                unopened[b] = 1
        while opened:
            q2 = []
            for b in opened:
                ans += candies[b]
                for bb in containedBoxes[b]:
                    if visited[bb] == 0:
                        if status[bb] == 1:
                            q2.append(bb)
                        else:
                            unopened[bb] = 1
                for k in keys[b]:
                    status[k] = 1
                    if unopened[k] == 1 and visited[k] == 0:
                        unopened[k] = 0
                        visited[k] = 1
                        q2.append(k)
            opened = q2
        return ans

class Solution:
    dp = {0: 0}
    def racecar(self, target: int) -> int:
        if target in self.dp:
            return self.dp[target]
        n = target.bit_length()
        if 2**n - 1 == target:
            self.dp[target] = n
        else:
            self.dp[target] = self.racecar(2**n - 1 - target) + n + 1
            for m in range(n - 1):
                self.dp[target] = min(self.dp[target], self.racecar(target - 2**(n - 1) + 2**m) + n + m + 1)
        return self.dp[target]

class Solution:
    def racecar(self, target: int) -> int:
        q = deque([(0, 1, 0)])
        encountered = set()
        while q:
            pos, spd, length = q.popleft()
            if (pos, spd) in encountered: continue
            else: encountered.add((pos, spd))
            if pos == target: 
                return length
            if (pos + spd, spd * 2) not in encountered:
                if abs(pos + spd) <= 2 * target + 1:
                    q.append((pos + spd, spd * 2, length + 1))
            revSpd = -1 if spd > 0 else 1
            if (pos, revSpd) not in encountered:
                q.append((pos, revSpd, length + 1))
        return -1

