class Solution:
    def racecar(self, target: int) -> int:

        steps = 0
        queue = deque([(0, 1)])
        cache = {(0,1)}
        while queue:
            for _ in range(len(queue)):
                p, s = queue.popleft()
                if p == target:
                    return steps
                p1,s1 = p+s, s*2
                p2 = p
                s2 = -1 if s > 0 else 1

                if -20000 <= p1 <= 20000 and (p1,s1) not in cache:
                    cache.add((p1,s1))
                    queue.append((p1,s1))
                if -20000 <= p2 <= 20000 and  (p2,s2) not in cache:
                    cache.add((p2,s2))
                    queue.append((p2,s2))
            steps += 1

class Solution:
    def racecar(self, target: int) -> int:
        nodes = [(0, 1)]
        seen, length = set([(0, 1), (0, -1)]), 0
        while nodes:
            new_nodes = []
            for pos, speed in nodes:
                if pos == target:
                    return length
                # A
                for new_pos, new_speed in [
                    (pos + speed, speed * 2),
                    (pos, -1 if speed > 0 else 1),
                ]:
                    if abs(new_speed) > 2 * target or abs(new_pos) > 2 * target:
                        continue
                    if (new_pos, new_speed) not in seen:
                        seen.add((new_pos, new_speed))
                        new_nodes.append((new_pos, new_speed))
            length += 1
            nodes = new_nodes
        return -1

