class Solution:
    def numTimesAllBlue(self, light):
        cnt, N = 0, len(light)
        bulbs = [0] * N
        for i, pos in enumerate(light, start = 1):
            pos -= 1
            if sum(bulbs[:pos]) == 2 * pos:
                bulbs[pos] = 2
                while pos + 1 < N and bulbs[pos+1] == 1:
                    bulbs[pos+1] = 2
                    pos += 1
                if sum(bulbs) == 2 * i:
                    cnt += 1
            else:
                bulbs[pos] = 1
        return cnt

