from functools import lru_cache
class Solution:
    def palindromePartition(self, s: str, k: int) -> int:
        n = len(s)
        if n == k:
            return 0
        @lru_cache(None)
        def cnt(left,right): # cost to make palindrome
            if left  >= right:
                return 0
            return cnt(left+1,right-1) + (s[left] != s[right])

        @lru_cache(None)
        def dp(length,partition):
            if partition == length:
                return 0
            if partition == 1:
                return cnt(0,length-1)
            return min(dp(prelength,partition-1) + cnt(prelength,length-1) for prelength in range(partition -1, length))


        return dp(n,k)

class Solution:
    def palindromePartition(self, s: str, k: int) -> int:
        n = len(s)
        visited = {}
        dic = {}
        def dfs(start, k):
            if (start, k) in dic:
                return dic[(start,k)]
            if k == 0:
                i = start
                j = n-1
                dic[(start, k)] = visited[(i,j)]
                return visited[(i,j)]
            count = float('inf')
            for i in range(start+1, n-k+1):
                count = min(count, visited[(start, i-1)]+dfs(i, k-1))

            dic[(start, k)] = count
            #print(dic)
            return count
        for j in range(n):
            for i in range(j, -1, -1):
                if i == j:
                    visited[(i,j)] = 0
                elif i == j-1:
                    if s[i] != s[j]:
                        visited[(i,j)] = 1
                    else:
                        visited[(i,j)] = 0
                else:
                    if s[i] == s[j]:
                        visited[(i,j)] = visited[(i+1,j-1)]
                    else:
                        visited[(i,j)] = visited[(i+1,j-1)]+1

        return dfs(0, k-1)

class Solution:
    def palindromePartition(self, s: str, k: int) -> int:
        # dp[i][k]: minimum cost to make s[:i] can be divided into k substring
        # xxxxxxxxxxxxxjxxxxxxi
        # dp[j-1][k-1]  s[j:i] 
        n = len(s)
        dp = [[math.inf for _ in range(k + 1)] for _ in range(n + 1)]
        dp[0][0] = 0

        def changes(start, end):
            cnt = 0
            while start < end:
                if s[start] != s[end]:
                    cnt += 1
                start += 1
                end -= 1
            return cnt

        for i in range(1, n + 1):
            for l in range(1, min(k, i) + 1):
                for j in range(l, i + 1):
                    dp[i][l] = min(dp[i][l], dp[j - 1][l - 1] + changes(j - 1, i - 1))

        return dp[n][k]

class Solution:
    def palindromePartition(self, s: str, k: int) -> int:
        # dp[i][j] is to partition s[:i] into j groups
        n = len(s)
        dp = [[float('inf')]*(k+1) for _ in range(n+1)]

        dp[0][0] = 0
        def cald(s):
            if len(s)==1:
                return 0
            else:
                lo, hi = 0, len(s)-1
                ans = 0
                while lo<hi:
                    if s[lo]!=s[hi]:
                        ans += 1
                    lo += 1
                    hi -= 1
                return ans

        for i in range(1,n+1): # to s[:i]
            for j in range(1,k+1):
                for h in range(j-1,i): # split into dp[h][] and s[h:i]
                    dp[i][j] = min(dp[i][j], dp[h][j-1]+ cald(s[h:i])  )
        return dp[n][k]

class Solution:
    def canConvertString(self, s: str, t: str, k: int) -> bool:
        if len(s) != len(t):
            return False

        c = Counter((ord(c2) - ord(c1)) % 26 for c1, c2 in zip(s, t))
        return k >= max(
            (m + 26 * (count - 1) for m, count in list(c.items()) if m),
            default = 0)

class Solution:
    def canConvertString(self, s: str, t: str, k: int) -> bool:
        if len(s) != len(t):
            return False
        count = [0 for _ in range(26)]
        for a, b in zip(s, t):
            if a == b:
                continue
            shift = (ord(b) - ord(a)) % 26
            count[shift] += 1
        max_shift = 0
        max_count = 0
        for i in range(25, -1, -1):
            if count[i] > max_count:
                max_shift = i
                max_count = count[i]
        if max_count < 1:
            return True
        # print('max_count', max_count, 'max_shift', max_shift)
        return (((max_count - 1) * 26) + max_shift) <= k

class Solution:
    def canConvertString(self, s: str, t: str, k: int) -> bool:

        if len(s) != len(t):
            return False

        cnts = [0]*26
        for char_s, char_t in zip(s, t):
            if char_s == char_t:
                continue
            elif char_s < char_t:
                moves_req = ord(char_t) - ord(char_s)
            else:
                moves_req = 26 - ord(char_s) + ord(char_t)

            cnts[moves_req] += 1
            if moves_req > k or cnts[moves_req]-1 > ((k-moves_req)/26):
                return False
        return True

class Solution:
