        if len(s) != len(t): return False
        dic = {}
        for a, b in zip(s, t):
            gap = ord(b) - ord(a)
            single = gap if gap >= 0 else 26 + gap
            if single == 0: continue
            if single not in dic:
                dic[single] = 0
            else:
                dic[single] += 1
            # print(a, b, \" dic:\", dic)
            if dic[single] * 26 + single > k: return False
        return True

class Solution:
    def maxSideLength(self, mat: List[List[int]], threshold: int) -> int:
        dp = [[0 for _ in range(len(mat[0]) + 1)]for r in range(len(mat) + 1)]

        for r in range(1, len(mat) + 1):
            for c in range(1, len(mat[r-1]) + 1):
                dp[r][c] += mat[r-1][c-1]
                if not r and not c:
                    continue
                elif not r:
                    dp[r][c] += dp[r][c-1]
                    continue
                elif not c:
                    dp[r][c] += dp[r-1][c]
                    continue
                dp[r][c] += dp[r][c-1] + dp[r-1][c] - dp[r-1][c-1]

        # print(dp)
        highest = -1
        for r in range(1, len(dp)):
            r0= r1 = r
            c0= c1 = 1
            while r1 < len(dp) and c1 < len(dp[0]):

                result = dp[r1][c1] + dp[r0-1][c0-1] - dp[r1][c0-1] - dp[r0-1][c1]

                # print(f'r0:{r0} r1:{r1} c0:{c0} c1:{c1} result:{result}')
                if result <= threshold:
                    highest = max(r1-r0, highest)
                    r1 += 1
                    c1 +=1
                else:
                    r1 -=1
                    c0 +=1
                r1 = max(r0+1,r1)
                c1 = max(c0+1,c1)

        return highest + 1

class Solution(object):
     def smallestDistancePair(self, nums, k):
         def possible(guess):
             #Is there k or more pairs with distance <= guess?
             count = left = 0
             for right, x in enumerate(nums):
                 while x - nums[left] > guess:
                     left += 1
                 count += right - left
             return count >= k

         nums.sort()
         lo = 0
         hi = nums[-1] - nums[0]
         while lo < hi:
             mi = (lo + hi) // 2
             if possible(mi):
                 hi = mi
             else:
                 lo = mi + 1

         return lo

class Solution:
    def bagOfTokensScore(self, tokens: List[int], P: int) -> int:
        tokens = sorted(tokens)
        left = 0
        right = len(tokens) - 1
        points = 0

        if len(tokens) == 1:
            if tokens[0] <= P:
                return 1
        if len(tokens) == 0:
            return 0
        while left < right:

            if tokens[left] <= P:
                P -= tokens[left]
                left += 1
                points += 1

            elif tokens[left] > P and points > 0:
                P += tokens[right]
                points -= 1
                right -= 1


            elif points == 0 and tokens[left] > P:
                break
        if P >= tokens[left]:
            points += 1
        return points

class Solution:
    def bagOfTokensScore(self, tokens: List[int], P: int) -> int:
        max_points, points = 0, 0
        tokens.sort()
        i, j = 0, len(tokens) - 1
        while i <= j:
            if P < tokens[i]:
                if i == j or points == 0: break
                P += tokens[j]
                points -= 1
                j -= 1
            points += 1
            P -= tokens[i]
            i += 1
            max_points = max(max_points, points)
        return max(max_points, points)

class Solution:
    def bagOfTokensScore(self, tokens: List[int], P: int) -> int:
        tokens.sort()
        if(not tokens or P < tokens[0]):
            return 0
        l, r = 0, len(tokens)-1
        points = 0

        while(l <= r):
            if(P >= tokens[l]):
                points += 1
                P -= tokens[l]
                l += 1
            else:
                if(r-l > 1):
                    points -= 1
                    P += tokens[r]
                    r -= 1
                else:
                    break
        return points

