class Solution:
     def totalNQueens(self, n):
         """
         :type n: int
         :rtype: int
         """
         placement = []

         def can_place_queen(row, col):
             for i, j in enumerate(placement):
                 if col == j or abs(col - j) == row - i:
                     # Same column as, or diagonally from other queen
                     return False
             return True

         def place_in_row(row):
             if row == n:
                 return 1

             count = 0
             for col in range(n):
                 if can_place_queen(row, col):
                     placement.append(col)
                     count += place_in_row(row + 1)
                     placement.pop()
             return count
         return place_in_row(0)

class Solution:
     def totalNQueens(self, n):
         """
         :type n: int
         :rtype: int
         """
         if n <= 0:
             return 0
         diag_lr = [True] * (2*n-1)
         diag_rl = [True] * (2*n-1)
         vert = [True] * n
         res = []

         def _check_board(x, y):
             return vert[y] and diag_lr[y-x+n-1] and diag_rl[x+y]

         def _helper(x):
             if x == n:
                 res.append(1)
                 return
             for y in range(n):
                 if _check_board(x, y):
                     vert[y] = False
                     diag_lr[y-x+n-1] = False
                     diag_rl[x+y] = False
                     _helper(x+1)
                     vert[y] = True
                     diag_lr[y-x+n-1] = True
                     diag_rl[x+y] = True

         _helper(0)
         return len(res)

