class Solution:
    def minCost(self, grid: List[List[int]]) -> int:
        right, left, down, up = (0, 1), (0, -1), (1, 0), (-1, 0)

        direction_map = {
            1: right,
            2: left,
            3: down,
            4: up
        }

        directions = [right, left, down, up]
        visited = set()

        def in_bounds(i, j):
            return 0 <= i < len(grid) and 0 <= j < len(grid[i])

        def dfs(i, j):                                           
            # not in bounds
            if not in_bounds(i, j) or (i, j) in visited:
                return []

            visited.add((i, j))

            sign = grid[i][j]
            direction = direction_map[sign]
            next_i, next_j = i + direction[0], j + direction[1]
            return [(i, j)] + dfs(next_i, next_j)


        reachable = dfs(0, 0)
        curr_cost = 0
        while reachable:
            next_reachable = []
            for (i, j) in reachable:
                if i == len(grid) - 1 and j == len(grid[i]) - 1:
                    return curr_cost

                for d in directions:
                    next_reachable += dfs(i + d[0], j + d[1])
            reachable = next_reachable
            curr_cost += 1

        return -1

class Solution:
    def leastOpsExpressTarget(self, x: int, target: int) -> int:
        @lru_cache(None)
        def calc(goal):
            if x == goal:
                return 0
            if x > goal:
                return min(goal*2 - 1, (x - goal) * 2)

            sums = x
            times = 0
            while sums < goal:
                times += 1
                sums *= x

            if sums == goal:
                return times

            if sums - goal < goal:
                return min(calc(sums - goal) + times + 1, calc(goal - (sums // x)) + times)

            return calc(goal - (sums // x)) + times            

        return calc(target)

from functools import lru_cache
class Solution:
    def leastOpsExpressTarget(self, x: int, target: int) -> int:
        @lru_cache(None)
        def search(t: int) -> int:
            if x == t:
                return 0
            if t < x:
                d1, d2 = t, x - t
                return min(2 * d1 - 1, 2 * d2)
            k1 = int(math.log(t, x))
            y1 = x ** k1
            if y1 == t:
                return k1 - 1
            total = k1 + search(t - y1)
            k2 = k1 + 1
            y2 = x ** k2
            if y2 <= 2 * t - y1:
                total = min(total, k2 + search(y2 - t))
            return total

        return search(target)

class Solution:
    def leastOpsExpressTarget(self, x: int, target: int) -> int:
        import math
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def f(x, target, depth):
            # print('  ' * depth, '开始计算', x, target)
            if target == 1:
                return 1

            res = target * 2 - 1
            if target < x:
                if x - target < target:
                    res = min(res, 1 + f(x, x - target, depth + 1))
            else:
                y = math.log(target, x)
                y_lower = int(y)
                p = pow(x, y_lower)
                cnt = target // p
                remain = target - cnt * p
                if y > y_lower:
                    res = min(res, y_lower * cnt + f(x, remain, depth + 1))
                    if p * x - target < target:
                        res = min(res, y_lower + 1 + f(x, p * x - target, depth + 1))
                else:
                    res = y_lower - 1
            return res

        return f(x, target, 0)

