    def soupServings(self, N: int) -> float:
        if N > 5000: return 1   # shortcut for large N (accurate to 1e-6)

        @lru_cache(None)
        def dp(a, b):
            if a <= 0 and b <= 0: return 0.5
            if a <= 0: return 1
            if b <= 0: return 0
