             tag, i = findtag(src, i)
             if not tag:
                 return False, j

             res, i = parseContent(src, i)

             e = i + len(tag) + 3
             return (True, e) if src[i: e] == '</' + tag + '>' else (False, j)

         def parseContent(src, i):
             j, res = i, False
             while i < len(src):
                 res, i = parseText(src, i)
                 if res:
                     continue

                 res, i = parseCDData(src, i)
                 if  res:
                     continue

                 res, i = parseTag(src, i)
                 if res:
                     continue

                 break

             return True, i

         def parseCDData(src, i):

             s = src.find('<![CDATA[', i)
             if s != i:
                 return False, i

             e = src.find(']]>', i)

             return (True, e+3) if e != -1 else (False, i)

         def parseText(src, i):
             j = i
             while i < len(src) and src[i] != '<':
                 i += 1

             return j != i, i

         def findtag(src, i):
             if src[i] != '<':
                 return "", i

             e = src.find('>', i+1)

             if e == -1 or e - i - 1 > 9 or e - i - 1 < 1:
                 return "", e

             s = 1
             while s < e - i and src[i+s].isupper():
                 s += 1

             return (src[i+1: e], e+1) if s >= e - i else ("", e)

         # start to check
         return parseTag(code, 0) == (True, len(code))

class Solution:
     def isValid(self, code):
         """
         :type code: str
         :rtype: bool
         """
         S=code
         CDATA_BEGIN='![CDATA['
         CDATA_END=']]>'


         def collect_tag(i):

             for j in range(i,len(S)):
                 if S[j]=='>':
                     break
             else:
                     return None
             return S[i+1:j]

         def valid_tag(tag):
             if 1<=len(tag)<=9 and all('A' <=c<= 'Z'  for c in tag):
                 return True
             else:
                 return False

         if not S or S[0]!='<':
             return False
         #print('###########1111############')
         tag=collect_tag(0)
         #print(tag)
         if not tag or not S.startswith('<{}>'.format(tag)) or not S.endswith('</{}>'.format(tag)) or not valid_tag(tag):

             return False

         S=S[len(tag)+2:-len(tag)-3]



         i=0
         stack=[]

         while i<len(S):

             if S[i]=='<':
                 tag=collect_tag(i)
                 #print(tag)
                 if not tag:

                     return False

                 if tag.startswith(CDATA_BEGIN):
                     while i<len(S)  and S[i:i+3]!=CDATA_END:
                         i+=1
                     if S[i:i+3]!=CDATA_END:
                         return False
                     i+=2
                 elif tag.startswith('/'):
                     tag=tag[1:]
                     if  not valid_tag(tag) or not stack or stack.pop()!=tag:
                         return False
                 else:
                     if not valid_tag(tag):
                         return False
                     stack.append(tag)

             i+=1
         return not stack

class Solution:
    def longestArithSeqLength(self, A: List[int]) -> int:
        length = len(A)
        onleft = set()
        onleftl = []
        onright = [0 for _ in range(501)]
        toextend = [{} for _ in range(501)]
        res = 2
        for v in A:
            onright[v] += 1
        for i in range(0, length):
            val = A[i]
            tex = toextend[val]
            onright[val] -= 1
            for lval in onleftl:
                diff = val - lval
                nextval = val + diff
                if nextval > 500 or nextval < 0 or onright[nextval] == 0:
                    continue
                if diff in tex:
                    c = tex[diff] + 1
                else:
                    c = 3
                if c > res:
                    res = c
                toextend[nextval][diff] = c
            if val not in onleft:
                onleftl.append(val)
                onleft.add(val)
        return res

class Solution:
    def longestArithSeqLength(self, A: List[int]) -> int:
        n = len(A)

        dp = [[2 for c in range(n)] for r in range(n)]

        visited = {}
        res = 2

        for i in range(n - 1):
            for j in range(i + 1, n):

                prev = A[i] * 2 - A[j]

                if prev < 0 or prev not in visited:
                    continue

                dp[i][j] = dp[visited[prev]][i] + 1

                res = max(res, dp[i][j])

            visited[A[i]] = i

        return res

