         :rtype: int
         """
         helper_dict = {}
         longest_start = 0
         longest_end = -1
         current_start = 0
         for char_index, char in enumerate(s):
             if char not in helper_dict or helper_dict[char] < current_start:
                 helper_dict[char] = char_index
             else:
