                if diff - r >= 0:
                    dp[diff - r] = max(dp.get(diff - r, 0), y + r)
                if r - diff >= 0:
                    dp[r - diff] = max(dp.get(r - diff, 0), y + diff) 
                # dp[abs(diff - r)] = max(dp.get(abs(diff - r), 0), y + min(diff, r)) 
        return dp[0]

from functools import lru_cache
class Solution:
    def tallestBillboard(self, rods):
        @lru_cache(None)
        def dp(i, s):
            if i == len(rods):
                return 0 if s == 0 else float('-inf')
            return max(dp(i + 1, s),
                       dp(i + 1, s - rods[i]),
                       dp(i + 1, s + rods[i]) + rods[i])

        return dp(0, 0)

class Solution:
    def tallestBillboard(self, rods):
        mem = {}
        def dp(i, s):
            if (i, s) in mem: return mem[(i, s)]
            if i == len(rods):
                return 0 if s == 0 else float('-inf')
            res = max(dp(i + 1, s),
                      dp(i + 1, s - rods[i]),
                      dp(i + 1, s + rods[i]) + rods[i])
            mem[(i,s)] = res
            return res

        return dp(0, 0)

class Solution:
    def exclu(self,nums):
        # whether we can find two elements x and y in nums so that x & y == 0
        n=len(nums)
        if n<=1: return False
        if n<=4:
            for x in nums:
                for y in nums:
                    if x & y ==0: return True
            return False

        set0,set1=set(),set()
        for x in nums:
            if x & 1 : set1.add(x>>1)
            else: set0.add(x>>1)
        if set0:
            if self.exclu(set0): return True
            if set1:  return self.exclu2(set0,set1)
        return False

    def exclu2(self,set0,set1):
        # whether we can find x in set0 and y in set1 so that x & y == 0
        # set0 and set1 are not empty
        if len(set0)==0 or len(set1)==0: return False
        if len(set1)==1:
            x=next(iter(set1))
            for y in set0: 
                if x & y ==0: return True
            return False

        if len(set0)==1:
            x=next(iter(set0))
            for y in set1: 
                if x & y ==0: return True
            return False

        if len(set0)<=8 and len(set1)<=8:
            for x in set0:
                for y in set1:
                    if x & y ==0: return True
            return False

        set00,setx0,set01,set11=set(), set(), set(), set() 
        for x in set0:
            setx0.add(x>>1)
            if x & 1 ==0: set00.add(x>>1)
        for x in set1:
            if x & 1 : set11.add(x>>1)
            else: set01.add(x>>1)

        if set00 and set11 and self.exclu2(set00,set11): return True
        if set01 and setx0 and self.exclu2(set01,setx0): return True
        return False

