        s1,s2, evil = [list(map(ord, i)) for i in args]
        mod = 10 ** 9 + 7

        def kmp(l, c):
            while l and evil[l] != c: l = f[l-1]
            if evil[l] == c : l += 1
            return l

        f = [0] * len(evil) 
        for i in range(1, len(evil)):
