            if i == N : return 1
            ans = 0
            for char in range(f1 and 97 or s1[i], f2 and 123 or s2[i]+1):
                ans += dp(i+1, kmp(lcp, char ), f1 or char > s1[i], f2 or char < s2[i])
                ans %= mod 
            return ans 

        return dp()

