        def calc(a : List[int], b : List[int]):
            from collections import defaultdict
            freq = defaultdict(int)
            for ai in a:
                freq[ai] += 1
            _ans = 0
            for bi in b:
                t = bi * bi
                for k in freq:
                    if t % k != 0 or t/k not in freq : continue
