class Solution:
    def dieSimulator(self, n: int, rollMax: List[int]) -> int:

        dp = [[0 for _ in range(7)] for i in range(n+1)]
        kMod = 1e9 + 7

        for i in range(1, 7):
            dp[1][i] = 1

        # steps
        for i in range(2, n+1):

            # current value
            for j in range(1, 7):

                k = i-rollMax[j-1]

                # all the posibilities included invalid ones
                dp[i][j] = sum(dp[i-1])

                # take off invalid posibilities
                invalid = max(0, k) if k <= 1 else (sum(dp[k-1])-dp[k-1][j])
                dp[i][j] = ((dp[i][j]-invalid) % kMod+kMod) % kMod

        return int(sum(dp[-1]) % (kMod))

class Solution:
    def dieSimulator(self, n: int, rollMax: List[int]) -> int:

        dp = [[0 for _ in range(len(rollMax))] for _ in range(n + 1)]
        sums_dict = {}
        sums_dict[0] = 1
        for j in range(len(rollMax)):
            dp[1][j] = 1

        for i in range(2, n + 1):
            sums_dict[i - 1] = sum(dp[i - 1])
            for j in range(len(rollMax)):
                steps = rollMax[j] # number of steps we can go upwards
                k = 1
                ans = 0
                while k <= min(steps, i):
                    row_sum = sums_dict[i - k]
                    ans += row_sum - dp[i - k][j]
                    k += 1
                dp[i][j] = ans

        return sum(dp[n]) % (10**9 + 7)

