class Solution:
    def maxSatisfaction(self, satisfaction: List[int]) -> int:
        satisfaction.sort()

        positive_sum, positive_step, positive_count = 0, 0, 0
        for i in satisfaction:
            if i < 0:
                continue
            positive_count += 1
            positive_sum += positive_count*i
            positive_step += i

        negative_count = len(satisfaction) - positive_count
        result = [positive_sum]
        for i in range(negative_count):

            negative_sum = 0
            for j in range(i+1):
                negative_sum += satisfaction[negative_count-j-1]*(i-j+1)
            result.append(negative_sum + positive_sum + positive_step*(i+1))

        return max(result)

class Solution:
    def minFlips(self, mat: List[List[int]]) -> int:
        m = len(mat)
        n = len(mat[0])

        start = sum(val << (i*n + j) for i, row in enumerate(mat) for j, val in enumerate(row))

        queue = collections.deque([(start, 0)])
        seen = { start }

        dirs = [[0, 0], [0,1], [1, 0], [0, -1], [-1, 0]]
        while queue:
            # print(queue)
            current, d = queue.popleft()
            if current == 0:
                return d

            # for each index in matrix find neighbour
            for i in range(len(mat)):
                for j in range(len(mat[0])):
                    next_state = current

                    # importants dirs has [0, 0] we need flip the current element and neigbour
                    for dir_ in dirs:
                        new_i = i + dir_[0]
                        new_j = j + dir_[1]

                        if new_i >= 0 and new_i < len(mat) and new_j >= 0 and new_j < len(mat[0]):
                            next_state ^= (1 << (new_i * n + new_j )) # 0 xor 1 = 1, 1 xor 1 = 0

                    if next_state not in seen:
                        seen.add(next_state)
                        queue.append((next_state, d + 1))

        return -1

