class UF:
    def __init__(self,n):
        self.p=[i for i in range(n)]  # parent array
        self.s=[1]*n  # size array

    def find(self,x): # find the representative/root of x
        if self.p[x]!=x:
            self.p[x]=self.find(self.p[x])
        return self.p[x]

class Solution:
    M=100000
    sieve=[0]*(M+1) # stores the largest prime divisor of integers up to M
    for i in range(2,M+1):
        if sieve[i]!=0:
            continue
        for j in range(1,M//i+1):
            sieve[j*i]=i

    def largestComponentSize(self, A: List[int]) -> int:   
        g=UF(len(A))
        primes=defaultdict(list) # {q:[nums]} list of integers that's divisible by prime q
        for i,num in enumerate(A):
            while num>1:
                q=self.sieve[num]
                primes[q].append(i) # add the ith element to be divisible by q
                while num%q==0:
                    num//=q

        for l in primes.values():
            root=g.find(l[0]) # representative/root of the 1st integer divisible by q
            for i in l[1:]: # joins all components with root
                node=g.find(i)
                if node!=root:
                    if g.s[root]<g.s[node]: # connect the smaller set to the larger one (for efficiency)
                        root,node=node,root
                    g.p[node]=root
                    g.s[root]+=g.s[node]

        return max(g.s)

class DSU:
    def __init__(self, n):
        self.p = list(range(n))
        self.sz = [1]*(n)

    def find(self, x):
        if x == self.p[x]:
            return x
        self.p[x] = self.find(self.p[x])
        return self.p[x]

    def unite(self, x, y):
        x = self.find(x)
        y = self.find(y)
        if x == y:
            return
        if self.sz[x] < self.sz[y]:
            x, y = y, x
        self.p[y] = x
        self.sz[x] += self.sz[y]

class Solution:
    def largestComponentSize(self, a: List[int]) -> int:
        N = max(a)+1

        idx = [-1]*N
        for i, x in enumerate(a):
            idx[x] = i

        dsu = DSU(N)
        siv = [True]*N

        for i in range(2, N):
            if siv[i]:
                root = idx[i]
                for j in range(2*i, N, i):
                    siv[j] = False
                    if idx[j] != -1:
                        if root == -1:
                            root = idx[j]
                        dsu.unite(root, idx[j])

        return max(dsu.sz)

class Solution:
    def largestComponentSize(self, A: List[int]) -> int:
        primes = []
        for x in range(2, int(max(A)**0.5)+1):
            for y in primes:
                if x % y == 0:
                    break
            else:
                primes.append(x)

        factors = collections.defaultdict(list)         # compute factors of each 'a'
        for a in A:
            x = a
            for p in primes:
                if p*p > x:
                    break
                if x % p == 0:
                    factors[a].append(p)
                    while x % p == 0:
                        x //= p
            if x > 1:                                   # a new prime found
                factors[a].append(x)
                primes.append(x)

        primes = list(set(primes))
        n = len(primes)
        p2i = {p: i for i,p in enumerate(primes)}       # prime to index

        parent = [i for i in range(n)]                  # union-find on primes

        def find(i):
            if i != parent[i]:
                parent[i] = find(parent[i])
            return parent[i]

        def union(i,j):
            pi, pj = find(i), find(j)
            if pi != pj:
                parent[pi] = pj

        for a in A:
            if factors[a]:
                p0 = factors[a][0]
                for p in factors[a][1:]:                # link two primes if they are factors of 'a'
                    union(p2i[p0], p2i[p])

        count = collections.Counter(find(p2i[factors[a][0]]) for a in A if factors[a])      # each 'a' corresponds to a prime index
        return max(count.values())

