     def maxProfit(self, k, prices):
         """
         :type k: int
         :type prices: List[int]
         :rtype: int
         """
         if len(prices)<2:
             return 0
         if k<=0:
             return 0
         if k >= len(prices) / 2:
             return sum(i - j for i, j in zip(prices[1:], prices[:-1]) if i - j > 0)
         buy = []
