         for i in range(k):
             buy.append(-float("inf"))
             sell.append(-float("inf"))

         for i in prices:
             for j in range(k):
                 if j== 0:
                     buy[j] = max(buy[j], -i)
                     sell[j] = max(sell[j], i+buy[j])
