        # return dp[0][n - 1]


        @lru_cache(None)
        def dp(i, j):
            return min([dp(i, k) + dp(k, j) + A[i] * A[k] * A[j] for k in range(i + 1, j)] or [0])
        return dp(0, len(A) - 1)

class Solution:
    def minScoreTriangulation(self, A: List[int]) -> int:
        @lru_cache(maxsize=None)
        def helper(start, end):
            if start + 1 == end:
                return 0

            result = 0
            for k in range(start + 1, end):
                result = min(float('inf') if result == 0 else result,
                            helper(start, k) +
                            A[start] * A[k] * A[end] +
                            helper(k, end))
            return result
        return helper(0, len(A) - 1)

class Solution:
    def minScoreTriangulation(self, a: List[int]) -> int:
        n = len(a)
        dp = [[float('inf')]*n for _ in range(n)]
        for l in range(2, n):
            for i in range(n-l):
                j = i + l                
                for k in range(i+1, j):
                    dp[i][j] = min(dp[i][j], (dp[i][k] if k >= i + 2 else 0) + a[i]*a[k]*a[j]  + (dp[k][j] if j >= k + 2 else 0))
        return dp[0][n-1]

class Solution:
    def gcd(self, x, y):
        while y > 0:
            x, y = y, x % y
        return x

    def lcm(self, x, y):
        return x*y//self.gcd(x,y)

    def nthMagicalNumber(self, N: int, A: int, B: int) -> int:
        AB = self.lcm(A,B)

        def check(mid):
            ans = mid//A + mid//B - mid//(AB)
            return ans >= N

        lo, hi = 0, N*A
        while lo<hi:
            mid = (lo+hi)//2
            if check(mid):
                hi = mid
            else:
                lo = mid+1

        mod = 10**9+7
        return lo%mod

class Solution:
    def nthMagicalNumber(self, N: int, A: int, B: int) -> int:
        from fractions import gcd
        MOD = 10**9+7
        L = A/gcd(A,B)*B

        def max_unique_nums(x):
            return x//A+x//B-x//L

        lo = 0
        hi = N*min(A,B)
        while lo<hi:
            mid = (lo+hi)//2
            if max_unique_nums(mid)<N:
                lo =  mid + 1
            else:
                hi = mid
        return lo%MOD

class Solution:
    def nthMagicalNumber(self, N: int, A: int, B: int) -> int:
        from fractions import gcd
        MOD = 10**9 + 7

        L = A / gcd(A, B) * B
        M = L / A + L / B - 1
        q, r = divmod(N, M)

        if r == 0:
            return int(q * L) % MOD

        heads = [A, B]
        for _ in range(int(r) - 1):
            if heads[0] <= heads[1]:
                heads[0] += A
            else:
                heads[1] += B

        return int(q * L + min(heads)) % MOD

class Solution:
    def nthMagicalNumber(self, N: int, A: int, B: int) -> int:
        ## official solution
        def gcd(x, y):
            if y==0:
                return x
            return gcd(y, x%y)

        MOD = 10**9 + 7
        ## Least common multiple of A and B
        L = A // gcd(A, B) * B
        M = L//A + L//B - 1
        q, r = divmod(N, M)

        if r == 0:
            return q*L%MOD

        increments = [A, B]
        for _ in range(r-1):
            if increments[0]<=increments[1]:
                increments[0] += A
            else:
                increments[1] += B
        return (q*L+min(increments))%MOD

