    def kConcatenationMaxSum(self, arr: List[int], k: int) -> int:
        oneArrSum = sum(arr)
        twoArr = arr + arr

        def findMaxSub(array):
            if len(array) == 1:
                return array[0]

            cur = 0
            small = 0
            ret = -999999
            for i in array:
                cur += i
                small = cur if cur < small else small
                ret = cur - small if cur - small > ret else ret

            return 0 if ret < 0 else ret

        if not arr:
            return 0
        if k == 1:
            return findMaxSub(arr)

        ret = findMaxSub(twoArr)
        if oneArrSum > 0 and k > 2:
            ret += (k-2)*oneArrSum
        return ret % (10**9 + 7)

class Solution:
    def kConcatenationMaxSum(self, arr: List[int], k: int) -> int:
        if not arr or k == 0: return 0
        N = 10 ** 9 + 7
        n = len(arr)
        accu = [0] * (n+1)
        for i in range(1,n+1):
            accu[i] = accu[i - 1] + arr[i - 1]
        s = accu[-1]
        accuMaxL = max(accu)
        accuMaxR = s - min(accu)
        a0, sMax = 0, 0
        for a in accu:
            a0 = min(a,a0)
            sMax = max(sMax, a - a0)
        if sMax <= 0:
            return 0
        elif k == 1:
            return sMax
        elif s <= 0:
            ans = max(sMax, accuMaxR + accuMaxL)
            return ans
        elif (sMax - accuMaxL - accuMaxR)/k > s:
            return sMax
        else:
            ans = accuMaxR + accuMaxL % N
            for i in range(k - 2):
                ans = (ans + s) % N
            return ans

class Solution:
    def kConcatenationMaxSum(self, arr: List[int], k: int) -> int:
        def getMaximumSum(subArr, t):
            subArrT = subArr.copy()
            for i in range(t-1):
                subArrT.extend(subArr) 
            nS = len(subArrT)
            maxSum = 0
            rSum = 0
            for i in range(nS):
                if ((rSum+subArrT[i]) < 0):
                    rSum = 0
                    continue
                else:
                    rSum += subArrT[i]
                    if (rSum > maxSum):
                        maxSum = rSum
            return maxSum
        def getHeadSum(subArr):
            headSum = 0
            nS = len(subArr)
            rSum = 0
            for i in range(nS):
                rSum += subArr[i]
                if (rSum > headSum):
                    headSum = rSum
            return headSum
        headSum = getHeadSum(arr)
        tailSum = getHeadSum(arr[::-1])
        sumArr  = sum(arr)

        result = 0
        if (sumArr > 0):
            if (k == 1):
                result = getMaximumSum(arr,1)
            elif (k == 2):
                result = tailSum + headSum
            else:
                result = tailSum + (k-2)*sumArr + headSum
        else:
            if (k > 1):
                if ((headSum + tailSum) > result):
                    result = headSum+tailSum

            if (getMaximumSum(arr,1) > result):
                result = getMaximumSum(arr,1)

        return result%(10**9+7)

