class Solution:

    def numRollsToTarget(self, d: int, f: int, target: int) -> int:
        if target < d or target > d * f:
            return 0

        total_sum = 0
        cache_sum = []

        if target > d * (1 + f) / 2:
            target = d * (1 + f) - target

        for i in range(target, -1, -1):
            num = 0 if i > f else 1
            total_sum += num; 
            cache_sum.append(total_sum)
        cache_sum = cache_sum[::-1]
        cache_sum[0] = cache_sum[1]

        for i in range(2, d+1):
            total_sum = 0
            for j in range(target, -1, -1):
                total_sum += cache_sum[max(j-f, 0)] - cache_sum[j]
                cache_sum[j] = total_sum
        return cache_sum[-1] % (10**9+7)

class Solution:
    def numRollsToTarget(self, d: int, f: int, target: int) -> int:
        @lru_cache(None)
        def solve(s,t):
            if s == 0:
                if t == 0:return 1
                return 0
            ans = 0
            for i in range(1,f+1):
                if t >= i:
                    ans += solve(s - 1,t - i)
            return ans
        return solve(d,target) % (10**9+7)

class Solution:
    def numRollsToTarget(self, d: int, f: int, target: int) -> int:
        # dp[d][target] = sum(dp[d-1][target - w]) w in 1-f
        dp = {0: 1}
        MOD = 10 ** 9 + 7
        for i in range(d):
            ndp = {}
            for k, v in list(dp.items()):
                for w in range(1, f+1):
                    if k + w <= target: 
                        ndp[k+w] = (ndp.get(k+w, 0) + dp[k] ) % MOD
            dp = ndp.copy()
        return dp.get(target, 0)

