class Solution:
    def minSwap(self, A, B):
        # 这道题是说A和B的swap是相对应的位置swap
        # index的遍历是同时遍历A和B的

        # 状态就是当前处理的是第几位 + 这一位是不是swap过来的
        #                 start^       swapped^
        return self._dfs(A, B, start=0, swapped=False, memo={})

    def _dfs(self, A, B, start, swapped, memo):
        if start == len(A):
            return 0

        key = (start, swapped)
        if key in memo:
            return memo[key]

        res = 2 ** 31 - 1
        prev_a = A[start - 1] if start > 0 else -2 ** 31 - 1
        prev_b = B[start - 1] if start > 0 else -2 ** 31 - 1

        if A[start] > prev_a and B[start] > prev_b:
            res = min(res, self._dfs(A, B, start + 1, False, memo))

        # 注意这里不能跳过
        # 否则会漏掉一些case
        if A[start] > prev_b and B[start] > prev_a:
            A[start], B[start] = B[start], A[start]
            res = min(res, self._dfs(A, B, start + 1, True, memo) + 1)
            A[start], B[start] = B[start], A[start]

        memo[key] = res
        return res

class Solution:
    def minSwap(self, A: List[int], B: List[int]) -> int:
        n=len(A)
        mem = {}
        def rec(index,ifSwapped):
            if index==n:
                return 0
            elif (index,ifSwapped) in mem:
                return mem[(index,ifSwapped)]
            else:
                ans=float('inf')
                #Don't swap if possible
                if A[index]>A[index-1] and B[index]>B[index-1]:
                    ans=min(ans,rec(index+1,0))
                #Swap if possible
                if A[index]>B[index-1] and B[index]>A[index-1]:
                    A[index],B[index]=B[index],A[index] #Swap
                    ans=min(ans,1+rec(index+1,1))
                    A[index],B[index]=B[index],A[index] #Swap them back
                mem[(index,ifSwapped)]=ans
                return ans

        ans=float('inf')
        ans=min(ans,rec(1,0))
        A[0],B[0]=B[0],A[0]
        ans=min(ans,1+rec(1,1))
        A[0],B[0]=B[0],A[0]

        return ans

class Solution:
    def minSwap(self, A: List[int], B: List[int]) -> int:

        no, yes, n = 0, 1, len(A)
        for i in range(1, n):
            no_u, yes_u = n, n
            if A[i-1] < A[i] and B[i-1] < B[i]:
                no_u, yes_u = no, yes + 1
            if A[i-1] < B[i] and B[i-1] < A[i]:
                no_u = min(no_u, yes)
                yes_u = min(yes_u, no+1)  

            no, yes = no_u, yes_u
        return min(no, yes)

class Solution:
    def minSwap(self, A: List[int], B: List[int]) -> int:
        N = len(A)
        not_swap, swap = 0, 1
        for i in range(1, N):
            not_swap2 = swap2 = N 
            if A[i - 1] < A[i] and B[i - 1] < B[i]:
                swap2 = swap + 1
                not_swap2 = not_swap
            if A[i - 1] < B[i] and B[i - 1] < A[i]:
                swap2 = min(swap2, not_swap + 1)
                not_swap2 = min(not_swap2, swap)
            swap, not_swap = swap2, not_swap2
        return min(swap, not_swap)

class Solution:
    def catMouseGame(self, graph: List[List[int]]) -> int:
        N = len(graph)

        # What nodes could play their turn to
        # arrive at node (mouse, cat, turn) ?
        def parents(mouse, cat, turn):
            prev_turn = 3 - turn
            if prev_turn == MOUSE: 
                for m2 in graph[mouse]:
                    yield m2, cat, prev_turn
            else:
                for c2 in graph[cat]:
                    if c2:
                        yield mouse, c2, prev_turn

        DRAW, MOUSE, CAT = 0, 1, 2
        colors = collections.defaultdict(int)

        # degree[node] : the number of neutral children of this node
        degree = {}
        for mouse in range(N):
            for cat in range(N):
                degree[mouse, cat, MOUSE] = len(graph[mouse])
                degree[mouse, cat, CAT] = len(graph[cat]) - (0 in graph[cat])  # cat can not be at hole 0

        # enqueued : all nodes that are colored
        queue = collections.deque([])
        for cat in range(N):
            for turn in [MOUSE, CAT]:
                # color MOUSE for all node with mouse=0
                mouse = 0
                colors[mouse, cat, turn] = MOUSE
                queue.append((mouse, cat, turn, MOUSE))
                # color CAT for all node with mouse = cat !=0, cat can not be at hole 0
                if cat > 0:
                    mouse = cat
                    colors[mouse, cat, turn] = CAT
                    queue.append((mouse, cat, turn, CAT))

        # percolate
        while queue:
            mouse, cat, turn, color = queue.popleft()
            for prev_mouse, prev_cat, prev_turn in parents(mouse, cat, turn):
                # if this parent is not colored :
                if colors[prev_mouse, prev_cat, prev_turn] is DRAW:
                    # if the parent can make a winning move (ie. mouse to MOUSE), do so
                    if prev_turn == color: # winning move
                        colors[prev_mouse, prev_cat, prev_turn] = color
                        queue.append((prev_mouse, prev_cat, prev_turn, color))
                        if prev_mouse == 1 and prev_cat == 2 and prev_turn == MOUSE: 
                            return color
                    # else, this parent has degree[parent]--, and enqueue if all children
                    # of this parent are colored as losing moves
                    else:
                        degree[prev_mouse, prev_cat, prev_turn] -= 1
                        if degree[prev_mouse, prev_cat, prev_turn] == 0:
                            colors[prev_mouse, prev_cat, prev_turn] = 3 - prev_turn
                            queue.append((prev_mouse, prev_cat, prev_turn, 3 - prev_turn))
                            if prev_mouse == 1 and prev_cat == 2 and prev_turn == MOUSE: 
                                return color

        return colors[1, 2, 1] # mouse at 1, cat at 2, MOUSE turn

class Solution:
    def catMouseGame(self, graph: List[List[int]]) -> int:
        n = 0
        for i in range(len(graph)):
            for j in range(len(graph[i])):
                n = max(n, graph[i][j])

        status = [[[0] * 3 for i in range(n + 1)] for j in range(n + 1)] # s[m][c][t]

        queue = []
        for i in range(1, n + 1):
            status[i][i][1] = 2
            status[i][i][2] = 2
            status[0][i][1] = 1
            status[0][i][2] = 1
            queue.append((i, i, 1))
            queue.append((i, i, 2))
            queue.append((0, i, 1))
            queue.append((0, i, 2))

        while queue:
            next_queue = []
            for element in queue:
                mouse = element[0]
                cat = element[1]
                turn = element[2]
                if turn == 1:
                    for cat_pre in graph[cat]:
                        if cat_pre == 0:
                            continue
                        if status[mouse][cat_pre][2] == 0:
                            status[mouse][cat_pre][2] = 1
                            for cat_alt in graph[cat_pre]:
                                if cat_alt == 0:
                                    continue
                                if status[mouse][cat_alt][1] == 2:
                                    status[mouse][cat_pre][2] = 2
                                    break
                                elif status[mouse][cat_alt][1] == 0:
                                    status[mouse][cat_pre][2] = 0
                            if status[mouse][cat_pre][2] > 0:
                                next_queue.append((mouse, cat_pre, 2))
                else:
                    for mouse_pre in graph[mouse]:
                        if status[mouse_pre][cat][1] == 0:
                            status[mouse_pre][cat][1] = 2
                            for mouse_alt in graph[mouse_pre]:
                                if status[mouse_alt][cat][2] == 1:
                                    status[mouse_pre][cat][1] = 1
                                    break
                                elif status[mouse_alt][cat][2] == 0:
                                    status[mouse_pre][cat][1] = 0
                            if status[mouse_pre][cat][1] > 0:
                                next_queue.append((mouse_pre, cat, 1))
            queue = next_queue

        return status[1][2][1]

class Solution:
    def catMouseGame(self, graph):
        CAT, MOUSE, n = 2, 1, len(graph)
        queue = []          # (cat, mouse, turn, winner)
        result = {}
        for i in range(n):
            for j in range(2):
                queue.append((i, 0, j, 1))
                result[(i, 0, j)] = 1
                if i > 0:
                    queue.append((i, i, j, 2))
                    result[(i, i, j)] = 2
                    queue.append((0, i, j, 1))
                    result[(0, i, j)] = 1

        cnt = {}
        for i in range(n):
            for j in range(n):
                cnt[(i, j, 0)] = len(graph[j])
                cnt[(i, j, 1)] = len(graph[i])

        while queue:
            cat, mouse, turn, winner = queue.pop()
            if turn == 1:   # cat move for next step, mouse move for last step
                if winner == 1:
                    for next_step in graph[mouse]:
                        if (cat, next_step, 1 - turn) not in result:
                            result[(cat, next_step, 1 - turn)] = winner
                            queue.append((cat, next_step, 1 - turn, winner))
                else:
                    for next_step in graph[mouse]:
                        if (cat, next_step, 1 - turn) not in result:
                            cnt[(cat, next_step, 1 - turn)] -= 1
                            if cnt[(cat, next_step, 1 - turn)] == 0:
                                result[(cat, next_step, 1 - turn)] = winner
                                queue.append((cat, next_step, 1 - turn, winner))
            else:
                if winner == 2:
                    for next_step in graph[cat]:
                        if next_step == 0:
                            continue
                        if (next_step, mouse, 1 - turn) not in result:
                            result[(next_step, mouse, 1 - turn)] = winner
                            queue.append((next_step, mouse, 1 - turn, winner))
                else:
                    for next_step in graph[cat]:
                        if next_step == 0:
                            continue
                        if (next_step, mouse, 1 - turn) not in result:
                            cnt[(next_step, mouse, 1 - turn)] -= 1
                            if cnt[(next_step, mouse, 1 - turn)] == 0:
                                result[(next_step, mouse, 1 - turn)] = winner
                                queue.append((next_step, mouse, 1 - turn, winner))
        if (2, 1, 0) in result:
            return result[(2, 1, 0)]
        return 0

