             if m == 2:
                 return 1 + cnt
             if m <= 4:
                 return 2 + cnt
             if m <= 6:
                 return 3 + cnt
             if m % 2 == 0:
                 cnt += 1
                 m = int(m / 2)
                 continue
             k = m % 4
             if k == 1:
                 cnt += 1
                 m = int(m - 1)
             elif k == 3:
                 cnt += 1
                 m = int(m + 1)

         return cnt

