class Solution:
    def lastSubstring(self, s: str) -> str:
        # loop to find the max lexicographic  
        # substring in the substring array 
        # l = \"\" 
        # for i in range(len(s)-1,-1,-1): 
        #     l = max(l, s[i:]) 
        #     print(s[i:])
        # return l

        if len(set(s)) == 1:
            return s 
        idx = len(s) - 1
        for i in range(len(s)-2, -1, -1):
            k = 0
            while idx+k < len(s):
                cur, stored = ord(s[i+k]), ord(s[idx+k])
