from collections import deque, defaultdict
class Solution:
    def shortestPathAllKeys(self, grid: List[str]) -> int:
        m,n = len(grid),len(grid[0])
        key_lock_loc = {ch:(i,j) for i,row in enumerate(grid) for j,ch in enumerate(row) if ch not in {'.','#'}}
        key_cnt = sum(key_lock in ('a','b','c','d','e','f')for key_lock in key_lock_loc)

        def bfs_from(src):
            i,j = key_lock_loc[src]
            seen = defaultdict(lambda: False)
            seen[i,j] = True
            # only locations which are not wall will be put into the queue
            dque = deque([(i,j,0)]) 
            dist = {}
            while dque:
                i,j,d = dque.popleft()
                ch = grid[i][j]
                if ch != src and ch != '.': # reaches lock or key
                    dist[ch] = d
                    continue
                # '#' or '.'
                for x,y in ((i-1,j),(i+1,j),(i,j-1),(i,j+1)):
                    if not (0<=x<m and 0<=y<n) or grid[x][y] == '#' or seen[x,y]:
                        continue
                    seen[x,y] = True
                    dque.append((x,y,d+1))
            return dist

        dists = {key_lock:bfs_from(key_lock) for key_lock in key_lock_loc}
        all_keys_bitmap = 2 ** key_cnt -1

        hq = [(0,'@',0)]
        final_dist = defaultdict(lambda: float('inf'))
        final_dist['@', 0] = 0
        while hq:
            d,ch,keys_bitmap = heapq.heappop(hq)
            if final_dist[ch,keys_bitmap] < d:
                continue
            if keys_bitmap == all_keys_bitmap:
                return d
            for next_key_lock, d2 in list(dists[ch].items()):
                keys_bitmap2 = keys_bitmap
                if next_key_lock.islower(): # key
                    keys_bitmap2 |= (1 <<(ord(next_key_lock) - ord('a')))
                elif next_key_lock.isupper(): # ch
                    if not(keys_bitmap &(1 <<(ord(next_key_lock) - ord('A')))):
                        continue
                if d + d2 < final_dist[next_key_lock, keys_bitmap2]:
                    final_dist[next_key_lock, keys_bitmap2]= d + d2
                    heapq.heappush(hq,(d+d2,next_key_lock,keys_bitmap2))
        return -1

class Solution:
    def shortestPathAllKeys(self, grid) -> int:
        from collections import deque
        import copy
        rows = len(grid)
        if rows == 0:
            return 0
        cols = len(grid[0])
        dirs = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        num_keys = 0
        start = [-1, -1]
        for i in range(rows):
            for j in range(cols):
                ch = grid[i][j]
                if 0 <= ord(ch) - ord('a') <= 5:
                    num_keys += 1
                if ch == '@':
                    start[0] = i
                    start[1] = j
        curr_level = deque()
        next_level = deque()
        visited = set()
        visited.add((0, start[0], start[1]))
        curr_level.append((0, start[0], start[1]))
        steps = 0
        while len(curr_level) > 0:
            for i in range(len(curr_level)):
                ori_keys, x, y = curr_level.popleft()
                for d in dirs:
                    keys = ori_keys
                    new_x = x + d[0]
                    new_y = y + d[1]
                    if new_x < 0 or new_x >= rows or new_y < 0 or new_y >= cols:
                        continue
                    ch = grid[new_x][new_y]
                    if ch == '#':
                        continue
                    ascii_minus_lower = ord(ch) - ord('a')
                    ascii_minus_upper = ord(ch) - ord('A')
                    if 0 <= ascii_minus_lower <= 5:
                        keys |= (1 << ascii_minus_lower)
                        if keys == ((1 << num_keys) - 1):
                            return steps + 1
                    if 0 <= ascii_minus_upper <= 5 and (((keys >> ascii_minus_upper) & 1) == 0):
                        continue
                    if (keys, new_x, new_y) not in visited:
                        visited.add((keys, new_x, new_y))
                        next_level.append((keys, new_x, new_y))
            curr_level = copy.deepcopy(next_level)
            next_level.clear()
            steps += 1
        return -1

class Solution:
    def __init__(self):
        self.DIR = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def shortestPathAllKeys(self, grid: List[str]) -> int:
        m, n = len(grid), len(grid[0])
        start_x, start_y = -1, -1
        target_keys = 0

        for i in range(m):
            for j in range(n):
                if grid[i][j] == '@':
                    start_x, start_y = i, j
                # elif grid[i][j].islower():
                elif grid[i][j] in 'abcdef':
                    target_keys |= 1 << (ord(grid[i][j]) - ord('a'))
                    # final_keys <<= 1
                    # final_keys |= 1

        pq = [(0, 0, start_x, start_y)]
        visited = set((0, start_x, start_y))

        while pq:
            curr_steps, curr_keys, x, y = heapq.heappop(pq)

            if curr_keys == target_keys:
                return curr_steps

            for delta_x, delta_y in self.DIR:
                next_x, next_y = x + delta_x, y + delta_y

                if not self.inbound(grid, next_x, next_y) or grid[next_x][next_y] == '#':
                    continue

                if grid[next_x][next_y] in 'ABCDEF':
                    if (curr_keys >> (ord(grid[next_x][next_y]) - ord('A'))) & 1:
                        next_keys = curr_keys
                    else:
                        continue
                elif grid[next_x][next_y] in 'abcdef':
                    next_keys = curr_keys | (1 << (ord(grid[next_x][next_y]) - ord('a')))
                else: # the next location is @ or .
                    next_keys = curr_keys

                if (next_keys, next_x, next_y) in visited:
                        continue

                heapq.heappush(pq, (curr_steps + 1, next_keys, next_x, next_y))
                visited.add((next_keys, next_x, next_y))
        return -1

    def inbound(self, grid, x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0])

class Solution:
    def shortestPathAllKeys(self, grid: List[str]) -> int:
        m=len(grid)
        n=len(grid[0])

        # handles neighbor, returns neighbor next state
        def neighbor(i,j, keys):
            keys_list = list(keys)
            if grid[i][j] in ['.', '@']:
                return (i,j,keys)
            elif grid[i][j].islower():
                if grid[i][j] in keys_list: # already picked key, treat as empty cell
                    return (i,j,keys)
                else: # pick up new key
                    keys_list.append(grid[i][j])
                    new_keys=''.join(keys_list)
                    return (i,j,new_keys)
            elif grid[i][j].isupper():
                if grid[i][j].lower() in keys_list: # treat lock as empty cell if have the key
                    return (i,j,keys)
            return None

        def move(i,j,keys):
            nexts=[]
            if i>0:
                nei = neighbor(i-1,j,keys)
                if nei:
                    nexts.append(nei)
            if i<m-1:
                nei=neighbor(i+1,j,keys)
                if nei:
                    nexts.append(nei)
            if j>0:
                nei=neighbor(i,j-1,keys)
                if nei:
                    nexts.append(nei)
            if j<n-1:
                nei= neighbor(i,j+1,keys)
                if nei:
                    nexts.append(nei)
            return nexts

        def get_start_and_keys():
            x, y, keys = -1, -1, 0
            for i in range(m):
                for j in range(n):
                    if grid[i][j]=='@':
                        x, y = i, j
                    elif grid[i][j].islower():
                        keys +=1
            return x, y, keys

        i0, j0, total_keys = get_start_and_keys()
        q=deque()
        start_point = (i0, j0, '')
        q.append(start_point)
        visited=set()
        visited.add(start_point)
        steps = -1
        while q:
            size=len(q)
            steps +=1
            for x in range(size):
                pop=q.popleft()
                i=pop[0]
                j=pop[1]
                keys=pop[2]
                if len(keys)==total_keys:
                    return steps
                for nex in move(i,j,keys):
                    if nex not in visited:
                        q.append(nex)
                        visited.add(nex)
        return -1

