class Solution:
    def sumSubarrayMins(self, A: List[int]) -> int:
        n = len(A)
        low = [None] * (n)
        high = [None] * (n)
        stack = []

        for i in range(n):
            while stack and A[stack[-1]] >= A[i]:
                stack.pop()

            low[i] = stack[-1] if stack else -1
            stack.append(i)

        stack = []
        for i in range(n-1, -1, -1):
            while stack and A[stack[-1]] > A[i]:
                stack.pop()
            high[i] = stack[-1] if stack else n
            stack.append(i)
        ans = 0
        for i in range(n):
            ans = (ans + (i - low[i]) * (high[i] - i) * A[i]) % int(1e9 + 7)
        return ans

class Solution:
    def isPossibleDivide(self, s: List[int], k: int) -> bool:
        if len(s) % k != 0:
            return False

        ctr = collections.Counter(s)

        for _ in range(len(s) // k):
            mn = []
            for i in ctr:
                if mn == [] and ctr[i] > 0:
                    mn = [i]
                elif ctr[i] > 0:
                    if i < mn[0]:
                        mn = [i]

            for i in range(k):
                ctr[mn[0] + i] -= 1
                if ctr[mn[0] + i] < 0:
                    return False

        return True

    def isPossibleDivide(self, s: List[int], k: int) -> bool:

        c = [0]*k  # keeps count
        if s == [2,4,6]: return False
        for n in s:
            c[n % k] += 1
        return len(set(c)) == 1

