class Solution:
    def numOfSubarrays(self, arr: List[int], k: int, threshold: int) -> int:
        # sliding window
        minVal = k * threshold

        beg = 0
        end = k - 1
        total = 0
        currSum = 0

        for i in range(beg, end+1):
            currSum += arr[i]

        while end < len(arr):
            if beg != 0:
                currSum = currSum - arr[beg - 1] + arr[end] 

            if currSum >= minVal:
                total+= 1
            beg += 1
            end += 1

        return total

class Solution:
    def numOfSubarrays(self, arr: List[int], k: int, threshold: int) -> int:
        # subarry, not sub elements, can be resolved by using running sum

        cur = 0
        res = 0
        for i in range(k):
            cur += arr[i]
        if cur / k >= threshold:
            res += 1
        for i in range(k, len(arr)):
            cur = cur + arr[i] - arr[i - k]
            if cur / k >= threshold:
                res += 1
        return res

