             return -1

     def checkStartWith10(self, L,l):
         #print(L, l)
         if len(L)!=l:
             return False

         for w in L:
             if w.startswith('10') == False:
                 return False

         return True

     def validUtf8(self, data):
         """
         :type data: List[int]
         :rtype: bool
         """
         A= []
         for d in data:
             A.append(format(d, '08b'))

         i = 0

         while i < len(A):
             l = self.countLeadingOne(A[i])
             if l == -1:
                 return False

             if l > 1:
                 if self.checkStartWith10(A[i+1:i+l], l-1) == False:
                     return False

             i+=l

         return True

