class Solution:
    def minDifficulty(self, jobDifficulty: List[int], d: int) -> int:
        n = len(jobDifficulty)
        if d > n:
            return -1
        if d == n:
            return sum(jobDifficulty)

        dp = {}

        def moveOnce(d0, difficultyNow, i0):
            if d0 == d:
                return max(difficultyNow, max(jobDifficulty[i0:]))
            if n - i0-1 == d-d0:
                return max(jobDifficulty[i0], difficultyNow) + sum(jobDifficulty[i0+1:])

            if (d0, difficultyNow, i0) in dp:
                return dp[(d0, difficultyNow, i0)]

            subAns = min(moveOnce(d0, max(jobDifficulty[i0], difficultyNow), i0 + 1), max(jobDifficulty[i0], difficultyNow) + moveOnce(d0+1, jobDifficulty[i0+1], i0+1))

            dp[(d0, difficultyNow, i0)] = subAns

            return subAns

        return moveOnce(1, jobDifficulty[0], 0)

class Solution:
    def minDifficulty(self, jobDifficulty: List[int], d: int) -> int:
        N = len(jobDifficulty)
        if d > N: return -1
        memo = [[float('inf')] * (d + 1) for _ in range(N + 1)]
        memo[0][0] = 0
        for i in range(1, N + 1):
            for k in range(1, min(i, d) + 1):
                maxD = 0
                for j in range(i - 1, -1, -1):
                    maxD = max(maxD, jobDifficulty[j])
                    memo[i][k] = min(memo[i][k], memo[j][k - 1] + maxD)
        return memo[N][d]

class Solution:
    def minDifficulty(self, jobDifficulty: List[int], d: int) -> int:
        if d > len(jobDifficulty):
            return -1
        self.memo = {}
        self.mxs = []
        mx = 0
        for j in jobDifficulty:
            mx = max(mx, j)
            self.mxs.append(mx)
        return self.recurse(jobDifficulty, len(jobDifficulty) - 1, d)

    def recurse(self, jd, start, remain):
        # if start == 0:
        #     return jd[0]
        if remain == 1:
            # return max(jd[:start + 1])
            return self.mxs[start]

        if (start, remain) in self.memo:
            return self.memo[(start, remain)]

        mx = 0
        mn = float('inf')

        for j in range(start, 0, -1):
            curr = jd[j]
            mx = max(mx, curr)
            mn = min(mn, mx + self.recurse(jd, j - 1, remain - 1))
        self.memo[(start, remain)] = mn
        # print((start, remain), self.memo, mx, mn)
        return mn

class Solution:
    def minCost(self, houses: List[int], Cost: List[List[int]], m: int, n: int, target: int) -> int:
        @lru_cache(None)
        def dfs(i, j, k):
            if i == len(houses):
                if j == target:
                    return 0
                else:
                    return float('inf')

            if houses[i] != 0:
                return dfs(i + 1, int(houses[i] != k) + j, houses[i])

            cost = float('inf')
            for index, c in enumerate(Cost[i]):
                cost = min(cost, dfs(i + 1, int(index + 1 != k) + j, index + 1) + c)

            return cost

        return dfs(0, 0, 0) if dfs(0, 0, 0) != float('inf') else -1

class Solution:
    def minCost(self, houses: List[int], cost: List[List[int]], m: int, n: int, target: int) -> int:

        @lru_cache(None)
        def dp(i, prev, count):
            if count>target:
                return float('inf')
            if i == m:
                return 0 if count==target else float('inf')

            return min((cost[i][c-1] if c!=houses[i] else 0)+dp(i+1, c, count+(prev!=c)) for c in range(1,n+1) if not houses[i] or c==houses[i])
        ans = dp(0, houses[0], 1 if houses[0] else 0)
        return -1 if ans==float('inf') else ans

