class Solution:
     def maximumSwap(self, num):
         """
         :type num: int
         :rtype: int
         """
         s = str(num)
         self.res = s

         def swap(i, j):
             a, b = self.res[i], self.res[j]
             self.res = self.res[:i] + b + self.res[i + 1:]
             self.res = self.res[:j] + a + self.res[j + 1:]

         d = {}

         for i, c in enumerate(s):
             if c in d:
                 d[c].append(i)
             else:
                 d[c] = [i]

         c = 0
         for i in range(10)[::-1]:
             i = str(i)
             if i in d:
                 arr = d[i]
                 done = False

                 for e in arr:
                     if e != c:
                         swap(c, arr[-1])
                         done = True
                         break
                     c += 1

                 if done:
                     break

         return int(self.res)

class Solution:
     def maximumSwap(self, num):
         """
         :type num: int
         :rtype: int
         """
         import itertools

         # Convert num into a list of chars
         A = [c for c in str(num)]

         # Compute suffix max for A
         suff_max = list(itertools.accumulate(A[::-1], max))[::-1]

         # Compute char -> largest index in A
         last = {x : i for i, x in enumerate(A)}

         # Swap the first occurrence of A[i] < suff_max[i]
         for i, x in enumerate(A):
             if x < suff_max[i]:
                 A[i], A[last[suff_max[i]]] = A[last[suff_max[i]]], A[i]
                 break

         return int(''.join(A))

