        m = len(grids)
        n = len(grids[0])
        grid_list = [[list() for j in range(n)] for i in range(m)]
        for num, val in list(num_to_range.items()):
            for i in range(val[0], val[1]+1):
                for j in range(val[2], val[3]+1):
                    grid_list[i][j].append(num)

        paths = {val: set() for val in list(num_to_range)}
        for i, row in enumerate(targetGrid):
            for j, val in enumerate(row):
                for parent in grid_list[i][j]:
                    if parent != val:
                        paths[parent].add(val)

        parent_counter = {val: 0 for val in list(num_to_range)}
        for parent, childs in list(paths.items()):
            for child in childs:
                parent_counter[child] += 1

        queue = deque()
        for child, cnt in list(parent_counter.items()):
            if cnt == 0:
                queue.append(child)

        seen = set()
        while queue:
            parent = queue.popleft()
            seen.add(parent)
            for child in paths[parent]:
                parent_counter[child] -= 1
                if parent_counter[child] == 0:
                    queue.append(child)



        return len(seen) == len(num_to_range)

SIDE_LEFT = 'left'
SIDE_RIGHT = 'right'
SIDE_TOP = 'top'
SIDE_BOTTOM = 'bottom'

class Solution:
    def isPrintable(self, targetGrid: List[List[int]]) -> bool:

        # Step 1: Get the set of the different colours being used
        colour_set = set()
        for row in targetGrid:
            for cell in row:
                colour_set.add(cell)

        # Step 2: Determine the size of each rectangle and the colours that overlap
        colour_overlap_info = self.get_colour_boundaries_and_overlap(targetGrid, colour_set)
        #print(colour_set, colour_overlap_info)

        # Step 3: Loop over the overlapping info. With each pass, print from the last colours downward. In this way, we'll determine
        # which colours we will print going backwards. If we can't print a colour underneath in an iteration, we've failed
        remaining_colours = colour_set.copy()
        untangled_colours = set()
        while remaining_colours:
            new_untangled_colours = set()
            for colour in remaining_colours:
                # Remove any colours that have been untangled
                colour_overlap_info[colour] -= untangled_colours
                if len(colour_overlap_info[colour]) == 0:
                    # We just untangled this one!
                    new_untangled_colours.add(colour)

            # Check if we've untangled anything new. If not, exit
            #print(new_untangled_colours)
            if new_untangled_colours:
                untangled_colours |= new_untangled_colours  # Add them to the full set
                remaining_colours -= new_untangled_colours  # Remove them from the full list
            else:
                break

        return len(remaining_colours) == 0  # If we've untangled everything, there are no remaining colours and it can be printed


    def get_colour_boundaries_and_overlap(self, targetGrid, colour_set):
        # Determine the size of each rectangle and the colours that overlap
        colours_info = {}
        for colour in colour_set:

            # Get the boundaries
            boundaries = {}
            for row_index, row in enumerate(targetGrid):
                for col_index, cell in enumerate(row):
                    if cell == colour:
                        # Update the boundaries
                        if not boundaries:
                            # Initialize
                            boundaries = {
                                SIDE_LEFT: col_index,
                                SIDE_RIGHT: col_index,
                                SIDE_TOP: row_index,
                                SIDE_BOTTOM: row_index
                            }
                        else:
                            # Update the boundaries. Note that top can't move but left can
                            if boundaries[SIDE_LEFT] > col_index:
                                boundaries[SIDE_LEFT] = col_index
                            if boundaries[SIDE_RIGHT] < col_index:
                                boundaries[SIDE_RIGHT] = col_index
                            if boundaries[SIDE_BOTTOM] < row_index:
                                boundaries[SIDE_BOTTOM] = row_index
            #print(colour, boundaries)

            # Now that we have the boundaries, get the colours inside them
            overlapping_colours = set()
            for row_index in range(boundaries[SIDE_TOP], boundaries[SIDE_BOTTOM] + 1):
                for col_index in range(boundaries[SIDE_LEFT], boundaries[SIDE_RIGHT] + 1):
                    cell = targetGrid[row_index][col_index]
                    if cell != colour:
                        overlapping_colours.add(cell)

            # Save the data
            colours_info[colour] = overlapping_colours

        return colours_info

class Solution:
    from collections import defaultdict, Counter
    def isPrintable(self, targetGrid: List[List[int]]) -> bool:
        shapes = {}  # color: [min_r, max_r, min_c, max_c]

        for i, row in enumerate(targetGrid):
            for j, color in enumerate(row):
                if color not in shapes:
                    shapes[color] = [i, i, j, j]
                else:
                    shapes[color][0] = min(shapes[color][0], i)
                    shapes[color][1] = max(shapes[color][1], i)
                    shapes[color][2] = min(shapes[color][2], j)
                    shapes[color][3] = max(shapes[color][3], j)

        edges = defaultdict(set)

        for color, [min_r, max_r, min_c, max_c] in list(shapes.items()):
            for r in range(min_r, max_r + 1):
                for c in range(min_c, max_c + 1):
                    if targetGrid[r][c] != color:
                        edges[color].add(targetGrid[r][c])

        deps = Counter()
        for _, ts in list(edges.items()):
            for c in ts:
                deps[c] += 1

        layer = [c for c in list(shapes.keys()) if not deps[c]]
        while layer:
            new_layer = []
            for c in layer:
                for t in edges[c]:
                    deps[t] -= 1
                    if not deps[t]:
                        new_layer.append(t)
            layer = new_layer

        return all(not v for c, v in list(deps.items()))

class Solution:
    def isPrintable(self, targetGrid: List[List[int]]) -> bool:
        a = [(math.inf, math.inf, -math.inf, -math.inf) for _ in range(61)]
        source = [[0] * len(targetGrid[0]) for _ in targetGrid]
        for i in range(len(targetGrid)):
            for j in range(len(targetGrid[i])):
                a[targetGrid[i][j]] = (min(a[targetGrid[i][j]][0], j), min(a[targetGrid[i][j]][1], i), max(a[targetGrid[i][j]][2], j), max(a[targetGrid[i][j]][3], i))
        gr = defaultdict(set)
        for p in range(len(a)):
            x, y, z, t = a[p]
            if x != math.inf:
                for i in range(y, t + 1):
                    for j in range(x, z + 1):
                        if targetGrid[i][j] != p:
                            gr[p].add(targetGrid[i][j])
        visited = set()
        inp = set()
        def dfs(k):
            inp.add(k)
            for x in gr[k]:
                if x in inp:
                    return False
                elif x not in visited and not dfs(x):
                    return False
            inp.remove(k)
            visited.add(k)
            return True
        for i in range(61):
            if i not in visited and not dfs(i):
                return False
        return True

class Solution:
    def isPrintable(self, targetGrid: List[List[int]]) -> bool:

        top = defaultdict(lambda: float('inf'))
        bottom = defaultdict(lambda: -1)

        left = defaultdict(lambda: float('inf'))
        right = defaultdict(lambda: -1)

        for row in range(len(targetGrid)):
            for col in range(len(targetGrid[row])):
                color = targetGrid[row][col]

                top[color] = min(top[color], row)
                bottom[color] = max(bottom[color], row)

                left[color] = min(left[color], col)
                right[color] = max(right[color], col)

        edges = defaultdict(list)

        for row in range(len(targetGrid)):
            for col in range(len(targetGrid[row])):
                color = targetGrid[row][col]

                for otherColor in top:
                    if color != otherColor and top[otherColor] <= row <= bottom[otherColor] and left[otherColor] <= col <= right[otherColor]:
                        edges[otherColor].append(color)

        # detect if there's a cycle in directed graph
        nodestates = [0 for _ in range(61)] # 0 not visited, 1 being visited, 2 done

        def dfs(current):
            nodestates[current] = 1

            for neighbor in edges[current]:
                if nodestates[neighbor] == 1:
                    # detect an edge
                    return True
                elif nodestates[neighbor] == 0:
                    dfs(neighbor)

            nodestates[current] = 2

        cycleDetected = False
        for node in top:
            if nodestates[node] == 0:
                if dfs(node):
                    cycleDetected = True
                    break

        return not cycleDetected

class Solution:
     def canCross(self, stones):
         """
         :type stones: List[int]
         :rtype: bool
         """
         if stones == []: return False
         if len(stones) == 1: return True
         diff = [0]*len(stones)

         for i in range(1,len(stones)):
             if stones[i] - stones[i-1] > i: return False

         stk = [(0, 0)]
         dictt = {}
         for idx, stone in enumerate(stones):
             dictt[stone] = idx
         while stk:
             idx, prevjump = stk.pop()

             for k in range(max(1, prevjump-1), prevjump+2):
                 if stones[idx] + k in dictt:
                     x = dictt[stones[idx] + k]
                     if x == len(stones) - 1: return True
                     stk.append((dictt[stones[idx]+k], k))

         return False

class Solution:
     def canCross(self, stones):
         """
         :type stones: List[int]
         :rtype: bool
         """
         target, stones, memo = stones[-1], set(stones), set()

         return self.dfs(stones, 1, 1, target, memo)

     def dfs(self, stones, pos, jump, target, memo):
         if (pos, jump) in memo:
             return False
         if pos == target:
             return True
         if pos not in stones or jump <= 0:
             return False

         for j in (jump-1, jump, jump+1):
             if self.dfs(stones, pos+j, j, target, memo):
                 return True
         memo.add((pos, jump))   # record bad position and jump
         return False

class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        coins.sort(reverse=True)
        n, res = len(coins), amount + 1

        def dfs(index, target, cnt):
            nonlocal res
            if cnt + (target + coins[index] - 1) // coins[index] >= res:
                return

            if target % coins[index] == 0:
                res = cnt + target // coins[index]
                return

            if index == n - 1:
                return

            for i in range(target // coins[index], -1, -1):
                dfs(index + 1, target - coins[index] * i, cnt + i)

        dfs(0, amount, 0)
        return -1 if res > amount else res

class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        if not coins or amount < 0:
            return -1
        elif amount == 0:
            return 0

        coins.sort(reverse = True)
        visited = set()
        q = collections.deque([])
        for c in coins:
            if c == amount:
                return 1
            elif c < amount:
                q.append(c)
                visited.add(c)

        count = 1
        while q:
            size = len(q)
            count += 1
            for _ in range(size):
                prev = q.popleft()
                for c in coins:
                    cur = prev + c
                    if cur == amount:
                        return count
                    elif cur < amount and cur not in visited:
                        visited.add(cur)
                        q.append(cur)

        return -1

class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        INVALID = 2**32
        dp = [INVALID] * (amount + 1)
        dp[0] = 0
        for coin in coins:
            for i in range(coin, amount + 1):
                if dp[i - coin] >= dp[i]: continue
                dp[i] = dp[i - coin] + 1
        return -1 if dp[amount] == INVALID else dp[amount]

class Solution:
    def coinChange(self, coins: List[int], amount: int) -> int:
        if amount == 0: return 0
        queue = [[amount, 0]]
        visited = {amount}
        for q in queue:
            for c in coins:
                if q[0] - c in visited: continue
                if q[0] == c: return q[1] + 1
                if q[0] > c:
                    visited.add(q[0] - c)
                    queue.append([q[0] - c, q[1] + 1])
        return -1

class Solution:
    def minSubarray(self, nums: List[int], p: int) -> int:
        need = sum(nums) % p
        if need == 0:
            return 0
        pos = {0: -1}
        total = 0
        ans = float('inf')
        for i, num in enumerate(nums):
            total = (total + num) % p
            target = (total - need) % p
            if target in pos:
                ans = min(ans, i - pos[target])
            pos[total] = i
        return ans if ans < len(nums) else -1

class Solution:
