        if rem == 0:
            return 0
        h_rem, min_len = {0: -1}, len(nums)
        cur_rem = 0
        for i in range(len(nums)):
            cur_rem = (cur_rem + nums[i]) % p
            h_rem[cur_rem] = i
            # print([rem, cur_rem, (cur_rem - rem) % p])
            if (cur_rem - rem) % p in h_rem:
                # print([min_len, i - h_rem[(cur_rem - rem) % p]])
