                if b == 0:
                    out.add(i)
                    out.add(a)
                if len(out) > 4: break
            if len(out) == 4:
                ans += sum(out)

        return ans

class Solution:
     def fractionToDecimal(self, numerator, denominator):
         """
         :type numerator: int
         :type denominator: int
         :rtype: str
         """
         if numerator*denominator < 0:
             add_negative = True
         else:
             add_negative = False
         numerator, denominator = abs(numerator), abs(denominator)

         integer_part = int(numerator//denominator)
         new_numerator = numerator-integer_part*denominator
         dict_residuals = {}
         digit_location = 0
         digit_array = []
         residual = new_numerator
         if residual == 0:
             if add_negative:
                 return "-"+str(integer_part)
             else:
                 return str(integer_part)
         is_repeating = True
         dict_residuals[residual] = 0
         while True:
             new_digit, residual = self.single_digit(residual, denominator)
             digit_location += 1
             if residual == 0:
                 dict_residuals[residual] = digit_location
                 digit_array.append(str(new_digit))
                 is_repeating = False
                 break
             elif residual in dict_residuals.keys():
                 digit_array.append(str(new_digit))
                 is_repeating = True
                 break
             else:
                 dict_residuals[residual] = digit_location
                 digit_array.append(str(new_digit))

         if not is_repeating:
             result = str(integer_part)+"."+"".join(digit_array)
         else:
             loc = dict_residuals[residual]
             result = str(integer_part)+"."+"".join(digit_array[0:loc])+"("+"".join(digit_array[loc:])+")"
         if add_negative:
             return "-"+result
         else:
             return result

     def single_digit(self, value, denominator):
         return int((10*value)//denominator), (10*value)%denominator

class Solution:
    def validateBinaryTreeNodes(self, n: int, leftChild: List[int], rightChild: List[int]) -> bool:

        root = set(range(n))
        for c in leftChild + rightChild:
            if c == -1:
                continue
            if c not in root:
                return False
            root.remove(c)

        if len(root) != 1:
            return False

        def dfs(node):
            if node == -1:
                return 0

            return 1 + dfs(leftChild[node]) + dfs(rightChild[node])

        return dfs(root.pop()) == n

class Solution:
    def validateBinaryTreeNodes(self, n: int, left_children: List[int], right_children: List[int]) -> bool:

        root = self.find_root(n, left_children, right_children)
        if root == -1:
            return False

        return self.helper(root, n, left_children, right_children)

    def find_root(self, n, left_children, right_children):
        left_counter = collections.Counter(left_children)
        right_counter = collections.Counter(right_children)
        for i in range(n):
            if i not in left_counter and i not in right_counter:
                return i

        return -1

    def helper(self, root, n, left_children, right_children):
        visited = set()
        if not self.dfs(root, left_children, right_children, visited):
            return False

        #print(visited)
        return len(visited) == n

    def dfs(self, root, left_children, right_children, visited):
        if root == -1:
            return True

        if root in visited:
            return False

        visited.add(root)
        left = self.dfs(left_children[root], left_children, right_children, visited)
        right = self.dfs(right_children[root], left_children, right_children, visited)

        return left and right

class Solution:
    def validateBinaryTreeNodes(self, n: int, leftChild: List[int], rightChild: List[int]) -> bool:
        parents = [(idx, 0) for idx in range(n)]

        def find(idx):
            original_idx = idx
            height = 0
            while parents[idx][0] != idx:
                height += 1
                idx = parents[idx][0]
            parents[original_idx] = (idx, 0)
            return parents[idx]

        # Returns false if the two elements are already in the same group
        def union(idx1, idx2):
            parent1, rank1 = find(idx1)
            parent2, rank2 = find(idx2)
            if parent1 == parent2:
                return False
            if rank1 > rank2:
                 parents[parent2] = (parent1, rank1)
            elif rank2 > rank1:
                 parents[parent1] = (parent2, rank2)
            else:
                 parents[parent1] = (parent2, rank2 + 1)
            return True
        # [1, 3, 3, 3]
        for idx1, idx2 in enumerate(leftChild):
            if idx2 == -1:
                continue
            if not union(idx1, idx2):
                return False

        for idx1, idx2 in enumerate(rightChild):
            if idx2 == -1:
                continue
            if not union(idx1, idx2):
                return False


        group, _ = find(0)
        for idx in range(n):
            if find(idx)[0] != group:
                return False
        return True

class Solution:
    def threeSumMulti(self, A: List[int], target: int) -> int:
        d = Counter(A)
        keys = sorted(d.keys())
        count = 0
        for i, a in enumerate(keys):
            if a <= target // 3:
                for b in keys[(i + 1) :]:
                    if target - a - b <= b:
                        break
                    elif target - a - b in d:
                        count += d[a] * d[b] * d[target - a - b]
            else:
                break
        for k in keys:
            if target != 3 * k and target - 2 * k in d:
                count += math.comb(d[k], 2) * d[target - 2 * k]
        if 3 * (target // 3) == target:
            count += math.comb(d[target // 3], 3)
        return count % (10**9 + 7)

