class Solution:
    def canReach(self, arr: List[int], start: int) -> bool:
        def jump(arr, start, n, g):
            g+=1
            if g>25:
                return False
            if start<0 or start>n-1:
                return False

            if arr[start] == 0:
                return True

            if jump(arr, start+arr[start],n,g):
                return True
            else:
                if jump(arr,start-arr[start],n,g):
                    return True
                else:
                    return False

        return jump(arr,start,len(arr),0)

class Solution:
    def canReach(self, arr: List[int], start: int) -> bool:

        memo = {}
        def dfs(i):
            if arr[i] == 0:
                return True
            if i in memo:
                return memo[i]
            memo[i] = False
            new_i = i + arr[i]
            if 0 <= new_i < len(arr):
                if dfs(new_i):
                    memo[i] = True
                    return True
            new_i = i - arr[i]
            if 0 <= new_i < len(arr):
                if dfs(new_i):
                    memo[i] = True
                    return True

            return memo[i]

        return dfs(start)

