            bx=True
            for k,v in dic.items():
                if let[k]<v:
                    words.pop(x)
                    bx=False
                    break
            if bx:x+=1
        word={}
        for w in words:
            word[w]=Counter(w)
        self.ans=0
        used=[]
        def run(x,cur,let):
            if x==len(words):
                return
            for i in range(x,len(words)):
                if i not in used:
                    tmp=dict(let)
                    bx=True
                    d=0
                    for k,v in word[words[i]].items():
                        let[k]-=v
                        d+=(sc[k]*v)
                        if let[k]<0:
                            bx=False
                            break
                    if bx:
                        used.append(i)
                        run(i+1,cur+d,let)
                        if cur+d>self.ans:
                            self.ans=max(self.ans,cur+d)
                        used.pop()
                        let=tmp
                    let=tmp
        run(0,0,let)
        return self.ans

class Solution:
    def rangeSum(self, nums: List[int], n: int, left: int, right: int) -> int:
        # B: partial sum of A
        # C: partial sum of B
        # Use prefix sum to precompute B and C
        A = nums
        B, C = [0] * (n + 1), [0] * (n + 1)
        for i in range(n):
            B[i + 1] = B[i] + A[i]
            C[i + 1] = C[i] + B[i + 1]

        # Use two pointer to
        # calculate the total number of cases if B[j] - B[i] <= score
        def count_sum_under(score):
            res = i = 0
            for j in range(n + 1):
                while B[j] - B[i] > score:
                    i += 1
                res += j - i
            return res

        # calculate the sum for all numbers whose indices are <= index k
        def sum_k_sums(k):
            score = kth_score(k)
            res = i = 0
            for j in range(n + 1):
                # Proceed until B[i] and B[j] are within score
                while B[j] - B[i] > score:
                    i += 1
                res += B[j] * (j - i + 1) - (C[j] - (C[i - 1] if i else 0))
            return res - (count_sum_under(score) - k) * score

        # use bisearch to find how many numbers ae below k
        def kth_score(k):
            l, r = 0, B[n]
            while l < r:
                m = (l + r) // 2
                if count_sum_under(m) < k:
                    l = m + 1
                else:
                    r = m
            return l

        # result between left and right can be converted to [0, right] - [0, left-1] (result below right - result below left-1)
        return (sum_k_sums(right) - sum_k_sums(left - 1))%(10**9 + 7)

