        arr = list(zip(position,speed))
        arr.sort(reverse=True)
        ans=1
        reach=(target-arr[0][0])/arr[0][1]
        for p,s in arr[1:]:
            curr = (target-p)/s
            if(curr>reach):
                ans+=1
                reach=curr
        return ans

class Solution:
    def carFleet(self, target: int, position: List[int], speed: List[int]) -> int:
        cars = sorted(zip(position, speed))
        times = [float(target - p) / s for p, s in cars]
        ans = 0
        while len(times) > 1:
            lead = times.pop()
            if lead < times[-1]: ans += 1  # if lead arrives sooner, it can't be caught
            else: times[-1] = lead # else, fleet arrives at later time 'lead'

        return ans + bool(times) # remaining car is fleet (if it exists)

class Solution:
    def check(self, target, p1, s1, p2, s2):
        if p1 == target and p2 == target:
            return True
        if p1 == target or p2 == target:
            return False
        d1 = float(target - p1)
        d2 = float(target - p2)
        if d1 / float(s1) <= d2 / float(s2):
            return True
        return False

    def solve(self, target, pos, speed):
        arr = []
        for i in range(len(pos)):
            p = pos[i]
            s = speed[i]
            arr.append((p, s))
        arr = sorted(arr)
        counter = 0
        ln = len(arr)
        i = ln-1
        # print(arr)
        while i >= 0:
            p2, s2 = arr[i]
            counter += 1
            j = i-1
            while j >= 0:
                p1, s1 = arr[j]
                if not self.check(target, p1, s1, p2, s2):
                    # print('not checked:', target, (p1, s1), (p2, s2))
                    break
                j-=1
            i = j
        return counter

    def carFleet(self, target: int, position: List[int], speed: List[int]) -> int:
        return self.solve(target, position, speed)

class Solution:
    def findKthBit(self, n: int, k: int) -> str:
        i = n - 1
        invert = False
        while i > 0:
            half_len = (2**(i + 1) - 1) // 2 
            if k == half_len + 1:
                return '1' if not invert else '0'

            if k > half_len:
                k = half_len - (k - half_len - 1) + 1
                invert = not invert
            i -= 1

        return '1' if invert else '0'

class Solution:
    def findKthBit(self, n: int, k: int) -> str:
        # S的奇数序列是 01010101，(3, 7, 11, ...)是1
        # 所以如果k是奇数，直接返回 (k >> 1) & 1

        # S的偶数序列是 1101100... (2, 4, 6, 8, 10, ...)
        # 这个序列的奇数序列是 10101010，(2, 6, 10, 14, ...), (2, 10, 18, ...)是1
        # 所以如果k是偶数，k >> 1就将偶数序列移动到奇数位置上 -> (1, 5, 9, ...)是1
        # 重复这个过程直到k为奇数，然后 (k >> 1) & 1 ^ 1

        # k // (k & -k) 相当于除到k为奇数。
        return str((k // (k & -k)) >> 1 & 1 ^ ((k & 1) ^ 1))

    def findKthBit_logn(self, n: int, k: int) -> str:
        cur, flip = 1 << (n - 1), 0
        while k > 1:
            if k & (k - 1) == 0:
                return str(flip ^ 1)
            if k > cur:
                k = 2 * cur - k
                flip ^= 1
            cur >>= 1

        return str(flip)

