        dp = [[]] * n
        dp[0] = [0]
        for i in range(1, n):
            dp[i] = dp[i - 1] + [1] +list(reversed([v ^ 1 for v in dp[i - 1]]))
        return str(dp[-1][k - 1])

class Solution:
    def findKthBit(self, n: int, k: int) -> str:

        def invert(s): return ''.join(['1' if c=='0' else '0' for c in s])
        def revStr(s): return ''.join(list(reversed(s)))

        counter = 1
        x = '0'
        while counter!=n:
            # make new string, increment counter
            x = x + '1' + revStr(invert(x))
            counter += 1

        return x[k-1]

