class Solution:
     def threeSumClosest(self, nums, target):
         """
         :type nums: List[int]
         :type target: int
         :rtype: int
         """
         nums = sorted(nums)
         res, diff = None, None
         for first in range(len(nums) - 2):
             if first and nums[first] == nums[first - 1]:
                 continue

             second, third = first + 1, len(nums) - 1
             if diff is None:
                 res = nums[first] + nums[second] + nums[third]
                 diff = abs(res - target)
             while second < third:
                 three_sum = nums[first] + nums[second] + nums[third]
                 if three_sum == target:
                     return target
                 elif three_sum < target:
                     partial = nums[first] + nums[third]
                     while second < third and nums[second] + partial  < target:
                         second += 1
                     tmp = nums[second - 1] + partial
                     if abs(tmp - target) < diff:
                         diff = abs(tmp - target)
                         res = tmp
                 else:
                     partial = nums[first] + nums[second]
                     while second < third and partial + nums[third] > target:
                         third -= 1
                     tmp = partial + nums[third + 1]
                     if abs(tmp - target) < diff:
                         diff = abs(tmp - target)
                         res = tmp
         return res

class Solution:
    def mctFromLeafValues(self, A: List[int]) -> int:
        res = 0
        while len(A) > 1:
            i = A.index(min(A))
            neighbors = []
            if i-1 >= 0:
                neighbors.append(A[i-1])
            if i+1 < len(A):
                neighbors.append(A[i+1])
            res += min(neighbors) * A.pop(i)
        return res

class Solution:
    def mctFromLeafValues(self, arr: List[int]) -> int:
        res = 0
        while len(arr) > 1:
            mini_idx = arr.index(min(arr))
            if 0 < mini_idx < len(arr) - 1:
                res += min(arr[mini_idx - 1], arr[mini_idx + 1]) * arr[mini_idx]
            else:
                res += arr[1 if mini_idx == 0 else mini_idx - 1] * arr[mini_idx]
            arr.pop(mini_idx)
        return res

class Solution:
    def mctFromLeafValues(self, arr: List[int]) -> int:
        if len(arr) <= 1: return 0
        min_i = 0
        min_val = arr[0] * arr[1]

        for i in range(1, len(arr) - 1):
            cur = arr[i] * arr[i + 1]
            if cur < min_val:
                min_val = cur
                min_i = i

        new_arr = arr[:min_i] + [max(arr[min_i], arr[min_i+1])] + arr[min_i+2:]
        return min_val + self.mctFromLeafValues(new_arr)

