class Solution:
    def minKBitFlips(self, A: List[int], K: int) -> int:
        l = len(A)
        flipped = [0] * l
        res = 0
        flipping_count = 0
        for i in range(l):
            if i >= K:
                flipping_count -= flipped[i - K]
            if (flipping_count % 2 == 0 and A[i] == 0) or (flipping_count % 2 == 1 and A[i] == 1):
                if i + K > l:
                    return -1
                flipped[i] += 1
                flipping_count += 1
                res += 1

        return res

class Solution:
    def minKBitFlips(self, A: List[int], K: int) -> int:
        flip_pos = 0
        flip_inds = []
        for i in range(len(A)):
            # find the correct current bit based on prior flips
            while flip_pos < len(flip_inds) and i - K + 1 > flip_inds[flip_pos]:
                flip_pos += 1

            cur_bit = A[i] ^ ((len(flip_inds) - flip_pos) % 2 != 0)

            if i > len(A) - K:
                if cur_bit == 0:
                    return -1
            else:
                if not cur_bit:
                    flip_inds.append(i)

        return len(flip_inds)

class Solution:
