class Solution:
    def longestDiverseString(self, a: int, b: int, c: int) -> str:
        if a == 0 and b == 0 and c == 0:
            return ''

        res = ''

        heap = [(-a, 'a'), (-b, 'b'), (-c, 'c')]
        heapq.heapify(heap)
        prev_val = 0
        prev_char = ''

        while heap:
            v, char = heapq.heappop(heap)
            if prev_val < 0:
                heapq.heappush(heap, (prev_val, prev_char))

            if abs(v) >= 2:
                if abs(v) > abs(prev_val):
                    res += char*2
                    v += 2
                else:
                    res += char
                    v += 1
            elif abs(v) == 1:
                res += char
                v +=1
            elif abs(v) == 0:
                break

            prev_val = v
            prev_char = char

        return res

class Solution:
    # https://leetcode.com/problems/longest-happy-string/discuss/564277/C%2B%2BJava-a-greater-b-greater-c
    def longestDiverseString(self, a: int, b: int, c: int, charA = 'a', charB = 'b', charC = 'c') -> str:
        if a<b: 
            return self.longestDiverseString(b, a, c, charB, charA, charC)
        if b<c: 
            return self.longestDiverseString(a, c, b, charA, charC, charB)
        # print(a, b, c, charA, charB, charC)
        if b==0: 
            return min(a, 2)*charA 
        use_a = min(2, a)
        use_b = 1 if a-use_a>=b else 0 
        return charA*use_a + charB*use_b + self.longestDiverseString(a-use_a, b-use_b, c, charA, charB, charC)

class Solution:
    def maxWidthRamp(self, A: List[int]) -> int:
        width = 0
        icandidate = [0]
        for i in range(len(A)):
            if A[i] < A[icandidate[-1]]:
                icandidate.append(i)
        for j in range(len(A) - 1, -1, -1):
            while icandidate and A[icandidate[-1]] <= A[j]:
                width = max(width, j - icandidate.pop())
        return width

class Solution:
    def maxWidthRamp(self, A: List[int]) -> int:
        stack = []
        n = len(A)
        for i in range(n):
            if not stack or A[stack[-1]] > A[i]:
                stack.append(i)

        res = 0
        i = n-1
        while i > res:
            while stack and A[stack[-1]] <= A[i]:
                res = max(res, i-stack[-1])
                stack.pop()
            i -= 1
        return res

class Solution:
    def maxWidthRamp(self, A: List[int]) -> int:
        sorted_indices = sorted(list(range(len(A))), key=lambda x: A[x])
        minimum_index = sorted_indices[0]
        answer = 0

        for i in range(1, len(sorted_indices)):
            if sorted_indices[i] > minimum_index:
                answer = max(answer, sorted_indices[i] - minimum_index)
            else:
                minimum_index = sorted_indices[i]

        return answer

