        def dp(left, right):

            if left > right:
                return 0

            if left == right:
                return 1

            maxk = 1
            length = 1
            #print(left, right)
            while(left + length <= right - length+1 ):
                #print(text[left:left+length],text[right-length+1:right+1])
                if text[left:left+length] == text[right-length+1:right+1]:
                    maxk = max(maxk, dp(left+length, right-length) + 2)

                length += 1


            return maxk

