            return 0

        A.sort()
        prev = A[0]
        res = 0
        for num in A[1:]:
            if num <= prev:
                prev += 1
                res += prev-num

            else:
                prev = num

        return res

class Solution:
    def minIncrementForUnique(self, A: List[int]) -> int:
        if not A:
            return 0

        n = len(A)
        A.sort()

        tail_num = A[0]
        result = 0
        for i in range(1, n):
            if A[i] > tail_num:
                tail_num = A[i]
            else:
                tail_num += 1

            # result = result + (tail_num - A[i])
            result += tail_num - A[i]

        return result

class Solution:
    def minIncrementForUnique(self, A: List[int]) -> int:
        count = collections.Counter(A)
        taken = []

        ans = 0
        for x in range(60000):
            if count[x] >= 2:
                taken.extend([x] * (count[x] - 1))
            elif taken and count[x] == 0:
                ans += x - taken.pop()
