class Solution:
    def jobScheduling(self, startTime: List[int], endTime: List[int], profit: List[int]) -> int:

        # max profit ending at time t
        dp = [(0,0)]

        task = [(startTime[i], endTime[i], profit[i]) for i in range(len(startTime))]
        task = sorted(task, key = lambda x: x[1])

        for s, e, p in task:
            noTaskProf = dp[-1][1]
            for end, pro in reversed(dp):
                # end, pro = dp[i]
                if end <= s:
                    doTaskProf = pro + p
                    break
            if doTaskProf > noTaskProf:
                dp.append((e, doTaskProf))
        return dp[-1][1]

from heapq import *

class Solution:
    def jobScheduling(self, startTime: List[int], endTime: List[int], profit: List[int]) -> int:
        jobs = sorted(zip(startTime, endTime, profit))
        heap = []
        max_profit = 0

        for start, end, p in jobs:
            while heap and heap[0][0] <= start:
                max_profit = max(max_profit, heappop(heap)[1])
            heappush(heap, (end, max_profit + p))

        for _, p in heap:
            max_profit = max(max_profit, p)
        return max_profit

class Solution:
    def jobScheduling(self, startTime: List[int], endTime: List[int], profit: List[int]) -> int:
        dp = [0]*(len(profit))
        intervals = [(startTime[i], endTime[i], profit[i]) for i in range(len(startTime))]
        intervals.sort(key=lambda x: x[1])
        dp[0] = intervals[0][2]
        for j in range(1, len(dp)):
            dp[j]=max(intervals[j][2], dp[j-1])
            l=0;r=len(intervals)-1
            while(l<r):
                mid=l+((r-l+1)>>1)
                if(intervals[mid][1]<=intervals[j][0]):
                    l=mid
                else:
                    r=mid-1
            if(intervals[j][0]>=intervals[l][1]):
                dp[j]=max(dp[j], intervals[j][2]+dp[l])
        return dp[-1]

class Solution:
    def binSearch(self, stack: List[int], target: int) -> List[int]:
        left = 0
        right = len(stack) - 1
        #[1,2,3] target= 4
        while left <= right:
            mid = (left + right + 1) // 2
            if stack[mid][1] > target:
                right = mid - 1
            elif stack[mid][1] == target or left == right and stack[mid][1] < target:
                return stack[mid]
            else:
                left = mid
        return None
    def jobScheduling(self, startTime: List[int], endTime: List[int], profit: List[int]) -> int:
        n = len(startTime)
        jobs = [[startTime[i], endTime[i], profit[i]] for i in range(n)]
        jobs.sort(key = lambda x : x[1])
        stack = []
        for i in range(n):
            job = jobs[i]
            prev = self.binSearch(stack, job[0])
            if prev is not None:
                job[2] += prev[2]
            if not stack or stack[-1][2] < job[2]:
                stack.append(job)
        return stack[-1][2]

class Solution:
     def rob(self, nums):
         """
         :type nums: List[int]
         :rtype: int
         """
         if not nums:
             return 0
         if len(nums)==1:
             return nums[0]
         return max(self.helper(nums[1:]), self.helper(nums[:-1]))

     def helper(self,nums):
         now = prev = 0
         for nxt in nums:
             now, prev = max(nxt+prev, now), now
         return now

class Solution:
     def rob(self, nums):
         """
         :type nums: List[int]
         :rtype: int
         """
         if len(nums)==1: return nums[0]
         last, now= 0, 0
         for i in nums[:-1]: last, now = now, max(last+i, now)
         ret=now
         last, now= 0, 0
         for i in nums[1:]: last, now = now, max(last+i, now)
         return max(ret, now)

class Solution:
     def rob(self, nums):
         """
         :type nums: List[int]
         :rtype: int
         """
         if not nums:
             return 0
         if len(nums) == 1:
             return nums[0]
         if len(nums) <= 3:
             return max(nums)
         def rob_line(lst):
             last, now = 0, 0
             for i in lst:
                 last, now = now, max(now, last + i)
             return now
         return max(rob_line(nums[:-1]), rob_line(nums[1:]))

class Solution:
     def helper(self, nums, cache = {}):
         if len(nums) == 0:
             return 0
         key = str(nums)
         if key in cache:
             return cache[key]
         cache[key] = max(nums[0] + self.helper(nums[2:]), self.helper(nums[1:]))
         return cache[key]
