class Solution:
    def minNumberOperations(self, target: List[int]) -> int:
        prev = -1
        ans = 0
        for num in target:
            if prev == -1:
                prev = num
                ans += num
                continue
            if num > prev:
                ans += (num - prev)
            #print(ans, num, prev)
            prev = num
        return ans

class Solution:
    def minNumberOperations(self, target: List[int]) -> int:
        ans=target[0]
        for i in range(1,len(target)):
            if target[i-1]<target[i]:
                ans+=target[i]-target[i-1]
        return ans

class Solution:
    def minNumberOperations(self, target: List[int]) -> int:
        ans = prev = 0
        for i in target:
            ans += max(0,i - prev)
            prev = i
        return ans

class Solution:
    def minNumberOperations(self, A: List[int]) -> int:
        res = pre = 0
        for a in A:
            res += max(0,a - pre)
            pre = a
        return res
